import{_ as e,o as l,c as r,af as i}from"./chunks/framework.B28LkSoM.js";const p=JSON.parse('{"title":"Java 学习路线  26 年最新零基础到精通一条龙（万人收藏⭐️） - 2026 全栈编程学习路线汇总：AIJavaGo前端（保姆级）  编程导航项目实战教程","description":"","frontmatter":{"title":"Java 学习路线  26 年最新零基础到精通一条龙（万人收藏⭐️） - 2026 全栈编程学习路线汇总：AIJavaGo前端（保姆级）  编程导航项目实战教程","published":"2026-09-07T00:00:00.000Z","tags":[],"description":"","image":"https://img.tsh520.cn/file/blog/post-covers/study-java-roadmap.webp","date":"2026-09-07T00:00:00.000Z","cover":false},"headers":[],"relativePath":"posts/学习路线/转载自编程导航鱼皮的学习Java学习路线.md","filePath":"posts/学习路线/转载自编程导航鱼皮的学习Java学习路线.md"}'),t={name:"posts/学习路线/转载自编程导航鱼皮的学习Java学习路线.md"};function o(n,a,h,s,u,c){return l(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1788739200000"},[...a[0]||(a[0]=[i('<blockquote><p>编程导航学习网站： <a href="https://www.codefather.cn/" target="_blank" rel="noreferrer">学编程、做项目、拿 Offer！</a></p><p>企业高频面试题库： <a href="https://www.mianshiya.com/" target="_blank" rel="noreferrer">开始刷题，面试遇原题！</a></p><p>精选简历模板大全： <a href="https://www.laoyujianli.com/" target="_blank" rel="noreferrer">1 分钟搞定简历！</a></p><p>AI 资源导航网站： <a href="https://ai.codefather.cn/" target="_blank" rel="noreferrer">获取最新 AI 黑科技！</a></p><p>1 对 1 模拟面试： <a href="https://ai.mianshiya.com/" target="_blank" rel="noreferrer">随时随地提升面试能力</a></p></blockquote><p>Java 求职高频面试题： <a href="https://www.mianshiya.com/bank/1983888023644901377" target="_blank" rel="noreferrer">开始刷题</a></p><h2 id="符号表" tabindex="-1">符号表 <a class="header-anchor" href="#符号表" aria-label="Permalink to &quot;符号表&quot;">​</a></h2><p>可以通过路‌‌‌‌线知识点前的⁢表⁢情⁢字⁢符，根⁡据自⁡己的⁡实际⁡情况选择学习：</p><ul><li>🌕 所有同学必须学习！！！</li><li>🌖 非常急着找工作，才可不学；目标大厂，必须学习！</li><li>🌗 急着找工作的话，可不学；目标大厂，建议学习</li><li>🌘 时间充足的话，再去学</li><li>⭐ 表示推荐资源</li></ul><h2 id="开篇介绍" tabindex="-1">开篇介绍 <a class="header-anchor" href="#开篇介绍" aria-label="Permalink to &quot;开篇介绍&quot;">​</a></h2><p>首先呢，我‌‌‌‌们要了解 Ja⁢⁢v⁢a⁢ 的应用场⁡⁡景和⁡就业⁡方向，看看和自己的学⁠⁠习目的⁠是否一致。</p><p>Java 是一门拥有 ‌‌‌‌20 多年历史的老牌编程语言，从诞生之初就⁢⁢⁢⁢凭借着 &quot;一次编写，到处运行&quot; 的特性风靡⁡⁡⁡⁡全球。时至今日，Java 由于优秀的特性、成熟稳定的生态以及庞大的开发者社区，依然是⁠⁠⁠⁠企业级应用开发的首选语言之一。</p><p><strong>为什么要学 Java 呢？</strong></p><p>很简单，因为 Java ‌‌‌‌岗位需求量大、就业机会多。无论是后端开发、安卓开⁢⁢⁢⁢发，还是大数据开发，Java 都能胜任。而且 J⁡⁡⁡⁡ava 的学习资源非常丰富，视频教程、开源项目应有尽有，非常适合自学。这也是鱼皮当时选择 Jav⁠⁠⁠⁠a、目前仍然主攻 Java 的原因。</p><p>特别是在 AI 时代，Java 程序员的价值不降反升！因为 AI 需要和业务系统深度结合，而 Java 正是最主流的业务开发语言。掌握 Java + AI 应用开发（比如 LangChain4j），将会拥有更强的竞争力。</p><blockquote><p>想了解更多 AI 工具和资源，可以访问鱼皮的 <a href="https://ai.codefather.cn/" target="_blank" rel="noreferrer">AI 资源大全</a> 。</p></blockquote><p>学好 Ja‌‌va，你能做什么⁢呢⁢？      ⁡  ⁡              ⁠    ⁠</p><p>可以开发企业管‌‌‌‌理系统、电商平台、社交应用、⁢⁢⁢⁢游戏后台、大数据处理系统，还⁡⁡⁡⁡可以开发 AI 应用（比如智能客服、AI 助手、自动化工⁠⁠⁠⁠具等），应用场景非常广泛。</p><h3 id="就业方向" tabindex="-1">就业方向 <a class="header-anchor" href="#就业方向" aria-label="Permalink to &quot;就业方向&quot;">​</a></h3><p>学习 Java 后，常见的就业方向有哪些呢？</p><p>主要包括：</p><ol><li>⭐️ Java 后端开发工程师：负责服务端业务逻辑开发，是 Java 最主流的就业方向。工作内容包括设计和实现后端接口、处理业务逻辑、操作数据库、对接第三方服务等。</li><li>Java 全栈开发工程师：既能做后端也能做前端，能够独立完成整个项目的开发。相比纯后端，需要额外掌握前端技术栈。</li><li>安卓开发工程师：使用 Java 或 Kotlin 开发安卓应用，需要额外学习安卓开发框架和移动端知识。</li><li>大数据开发工程师：使用 Java 进行大数据处理和分析，需要额外学习 Hadoop、Spark、Flink 等大数据技术栈。</li><li>架构师：在有丰富的开发经验后，可以往架构师方向发展，负责系统的整体设计和技术选型。</li><li>AI 应用开发工程师：在 AI 时代，越来越多的企业需要开发 AI 应用。Java 程序员可以学习 LangChain4j 等 AI 开发框架，结合后端技术开发 AI 应用，这是一个新兴且前景广阔的方向。</li></ol><h2 id="学习路线图" tabindex="-1">学习路线图 <a class="header-anchor" href="#学习路线图" aria-label="Permalink to &quot;学习路线图&quot;">​</a></h2><p>下面是完整的 Java 学习路线图，帮助大家理清学习脉络：</p><p><img src="https://pic.code-nav.cn/migrate_image/e36e183c24abf5ff634a59c4ebd0483b.png" alt="Java 学习路线思维导图"></p><h2 id="阶段-1-编程语言基础" tabindex="-1">阶段 1：编程语言基础 <a class="header-anchor" href="#阶段-1-编程语言基础" aria-label="Permalink to &quot;阶段 1：编程语言基础&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>培养兴趣、快速上手，能运行和编写简单的 Java 程序。</p><p>学完本阶段后‌‌‌‌，可以试着用 Java⁢⁢⁢⁢ 解决一些数学计算问题⁡⁡⁡⁡、编写图书管理系统等桌面端 GUI 程序，甚⁠⁠⁠⁠至是五子棋之类的小游戏。</p><h3 id="🌕-java-编程基础-45-天" tabindex="-1">🌕 Java 编程基础（45 天） <a class="header-anchor" href="#🌕-java-编程基础-45-天" aria-label="Permalink to &quot;🌕 Java 编程基础（45 天）&quot;">​</a></h3><h4 id="知识" tabindex="-1">知识 <a class="header-anchor" href="#知识" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>Java 特点（看不懂没事，别背！）</li><li>环境搭建</li><li>IDEA 开发工具 <ul><li>新建项目 <ul><li>运行调试</li><li>界面配置</li><li>插件管理</li></ul></li></ul></li><li><strong>Java 基础语法</strong><ul><li>数据类型 <ul><li>流程控制</li></ul></li></ul></li><li>数组</li><li><strong>面向对象</strong><ul><li>方法 <ul><li>重载</li><li>封装</li><li>继承</li><li>多态</li></ul></li></ul></li><li>抽象类</li><li>接口</li><li>枚举</li><li>常用类 <ul><li>String <ul><li>日期时间</li></ul></li></ul></li><li>集合类</li><li>泛型</li><li>注解</li><li>异常处理</li><li>多线程</li><li>IO 流</li><li>反射</li></ul><h4 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>1）坚持每天学习：‌‌‌‌初学一门语言时，一定要持续学习，不能⁢⁢⁢⁢中断！建议每天至少学习 2-3 小时⁡⁡⁡⁡，保持学习的连贯性。我当时学 Java 基础的时候，就是每天雷打不动地学⁠⁠⁠⁠，一个半月就把基础过了一遍。</p><p>2）多敲代码，多动手：想‌‌‌‌要学好编程，一定要多敲代码！千万不要只看视频不动⁢⁢⁢⁢手，那样永远学不会。建议先跟着视频或书上的例子敲⁡⁡⁡⁡一遍代码，然后试着自主编写代码，并完成课后练习。很多编程导航的鱼友刚开始学的时候也会犯这个错误，⁠⁠⁠⁠看完视频觉得都懂了，一写代码就懵了。</p><p>3）学会使用 Debu‌‌‌‌g：不理解代码也没关系，可以学习 Debug⁢⁢⁢⁢ 后，一行一行地打断点执行，查看程序的执行⁡⁡⁡⁡过程。千万不要觉得麻烦，养成习惯后真的能节省很多重复学习的时间。遇到 Bug 不要慌，学会⁠⁠⁠⁠看报错信息，学会用搜索引擎查找解决方案。</p><p>4）善用 AI 工具：这是 AI 时代，新时代的程序员一定要学会用 AI 工具！遇到不懂的概念，可以问 AI；遇到 Bug，可以让 AI 帮你分析；甚至可以让 AI 帮你写一些简单的代码。推荐使用鱼皮的 <a href="https://ai.codefather.cn/" target="_blank" rel="noreferrer">AI 资源大全</a> ，里面有各种好用的 AI 编程工具。</p><p><img src="https://pic.code-nav.cn/migrate_image/82ac3cc9149fca4f07c3052dfacb222c.webp" alt=""></p><p>但是记住，‌‌‌‌AI 是辅助⁢工⁢具⁢，⁢不能完⁡全依⁡赖，⁡自己⁡动手写代码还是最⁠重要⁠的。</p><p>5）不要死记硬‌‌‌‌背：Java 的语法和 AP⁢⁢⁢⁢I 非常多，不要试图全部⁡⁡⁡⁡记住。理解为主，多用几次自然就记住了，忘了就查文档。重点是理⁠⁠⁠⁠解编程的思想和解决问题的方法。</p><h4 id="经典面试题" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>为什么重写 equals 还要重写 hashcode？</li><li>== 和 equals 比较的区别</li><li>为啥有时会出现 4.0 - 3.6 = 0.40000001 这种现象？</li><li>final 关键字的作用</li><li>介绍 Java 的集合类</li><li>ArrayList 和 LinkedList 的区别</li></ol><p>更多 Java 基础面试题，推荐到面试鸭刷题：</p><ul><li><a href="https://www.mianshiya.com/bank/1787463103423897602" target="_blank" rel="noreferrer">Java 基础面试题</a></li><li><a href="https://www.mianshiya.com/bank/1788408712975282177" target="_blank" rel="noreferrer">Java 集合面试题</a></li></ul><h4 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1fh411y7R8" target="_blank" rel="noreferrer">韩顺平 - 零基础 30 天学会 Java</a> ：900 多集，顺序安排很合理，每个知识真正的打碎了，通俗、有示例、有实战、有思想</li><li><a href="https://www.liaoxuefeng.com/wiki/1252599548343744" target="_blank" rel="noreferrer">廖雪峰 Java 教程</a> ：图文教程，讲解清晰</li><li><a href="https://github.com/judasn/IntelliJ-IDEA-Tutorial" target="_blank" rel="noreferrer">IDEA 中文教程</a> ：可以作为课外书来看</li><li><a href="https://www.jianshu.com/p/454c71172c46" target="_blank" rel="noreferrer">IDEA Mac 快捷键指南</a></li><li><a href="https://www.jianshu.com/p/5de7cca0fefc" target="_blank" rel="noreferrer">IDEA Win 常用快捷键</a></li><li>《Head First Java》：经典入门书籍，适合零基础</li><li><a href="https://codegym.cc/zh" target="_blank" rel="noreferrer">Codegym 在线游戏</a> ：玩玩前几关培养兴趣不错，但后面收费了，不太建议用</li></ul><h3 id="🌖-java-8-及新版本特性-3-天" tabindex="-1">🌖 Java 8 及新版本特性（3 天） <a class="header-anchor" href="#🌖-java-8-及新版本特性-3-天" aria-label="Permalink to &quot;🌖 Java 8 及新版本特性（3 天）&quot;">​</a></h3><h4 id="知识-1" tabindex="-1">知识 <a class="header-anchor" href="#知识-1" aria-label="Permalink to &quot;知识&quot;">​</a></h4><p><strong>Java 8 核心特性【必学】：</strong></p><ul><li>Stream API</li><li>Lambda 表达式</li><li>新日期时间 API</li><li>接口默认方法</li><li>Optional 类</li></ul><p><strong>Java 新版本特性【了解】：</strong></p><p>随着 Java 的不‌断发展‌‌‌，从 Java 9 到最新的 Ja⁢va 25，每个版⁢⁢⁢本都引入了不少新特性。⁡虽然企业中 Java 8 和 ⁡⁡⁡Java 11 仍是主流，但了解新版本的特性能让你⁠在技术选型和代码优化时有更多选择           ⁠⁠⁠</p><p>比较重要的新特性包括：</p><ul><li>Java 17：记录类（Record）、密封类（Sealed Classes）、模式匹配增强</li><li>Java 21（LTS 长期支持版）：虚拟线程（Virtual Threads）、序列集合、字符串模板</li><li>Java 21 之后：更多语法糖和性能优化</li></ul><p>感兴趣的同学可以查看鱼皮整理的 <a href="https://www.codefather.cn/course/java/section/1962801453192523778" target="_blank" rel="noreferrer">Java 8 ~ 25 新特性大纲</a> ，里面详细介绍了每个版本的重要特性。</p><h4 id="学习建议-1" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-1" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>Java 8 是如今企‌‌‌‌业开发中最主流的 Java 稳定版本，在这个⁢⁢⁢⁢版本出现了很多实用的新特性，虽然面试考点不多⁡⁡⁡⁡，但能够提升编程效率，建议学习。Lambda 表达式和 Stream API 真的能让你⁠⁠⁠⁠的代码简洁优雅很多，强烈建议多练习。</p><p>此外，很多‌‌‌‌同学不怎么在简历上写⁢⁢⁢⁢自己会 Java 8⁡⁡⁡⁡，因此如果你把 Java 8 的知识点写⁠⁠⁠⁠在简历上，会大大加分的。</p><p>对于新版本特性，刚入门的‌‌‌‌同学先不用着急学，等你掌握了 Java 8 的⁢⁢⁢⁢核心知识、做过几个项目后，再回过头来了解新特性会⁡⁡⁡⁡更好。不过如果你有充足的时间，提前了解一下也没坏处，特别是虚拟线程（Virtual Thr⁠⁠⁠⁠eads）这种能显著提升并发性能的特性。</p><h4 id="经典面试题-1" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-1" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>Java 8 有哪些新特性？</li><li>Lambda 表达式的原理是什么？</li><li>Stream API 和传统的循环有什么区别？</li><li>HashMap 在 JDK 1.7 和 1.8 的区别？</li><li>Optional 类有什么作用，如何使用？</li></ol><h4 id="资源-1" tabindex="-1">资源 <a class="header-anchor" href="#资源-1" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1Kb411W75N" target="_blank" rel="noreferrer">宋红康 - 全网最全 Java 零基础入门教程</a> ：只看 Java 8 部分即可</li><li>⭐ <a href="https://www.bilibili.com/video/BV1haamzUE8m" target="_blank" rel="noreferrer">鱼皮 - Java 8 ~ 24 新特性讲解</a> ：全面讲解各版本新特性</li><li><a href="https://www.bilibili.com/video/BV1b5pCzGEPx" target="_blank" rel="noreferrer">鱼皮 - Java 25 新特性讲解</a> ：最新版本特性</li><li>⭐ <a href="https://www.codefather.cn/course/java/section/1962801453192523778" target="_blank" rel="noreferrer">Java 新特性大纲 - 编程导航</a></li><li>《Java 8 实战》：经典书籍</li><li>⭐ <a href="https://www.tutorialspoint.com/compile_java8_online.php" target="_blank" rel="noreferrer">在线编写运行 Java 8</a></li><li><a href="https://github.com/biezhi/30-seconds-of-java8" target="_blank" rel="noreferrer">Java 8 小代码片段</a></li></ul><h3 id="练手项目" tabindex="-1">练手项目 <a class="header-anchor" href="#练手项目" aria-label="Permalink to &quot;练手项目&quot;">​</a></h3><ul><li><a href="https://how2j.cn/module/104.html" target="_blank" rel="noreferrer">一本糊涂账</a> （记账系统）</li><li><a href="https://github.com/uboger/LibraryManager" target="_blank" rel="noreferrer">Java GUI 图书馆管理系统</a></li><li><a href="https://github.com/wangzhengyi/TankWar" target="_blank" rel="noreferrer">Java 坦克大战小游戏</a></li><li><a href="https://github.com/HelloClyde/Tetris-Swing" target="_blank" rel="noreferrer">Swing 俄罗斯方块</a></li><li><a href="https://github.com/xenv/SmallAccount" target="_blank" rel="noreferrer">小小记账本</a> （适合了解数据库的同学）</li></ul><h3 id="尾声" tabindex="-1">尾声 <a class="header-anchor" href="#尾声" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>学完了 Ja‌‌‌‌va 基础后，有些同学⁢⁢⁢⁢会感到迷茫了啊：感觉好⁡⁡⁡⁡像啥也做不出来，不知道下一步做什么，我这一身⁠⁠⁠⁠的本领该如何施展啊？</p><p>不要慌，也‌‌‌‌不要急着去学新技⁢⁢⁢术⁢，接下来我们要⁡⁡⁡多用⁡ Java 来写代码了，巩固⁠⁠⁠基础，但⁠是写什么呢？</p><p>当然是数据结构和算法！</p><h2 id="阶段-2-巩固基础" tabindex="-1">阶段 2：巩固基础 <a class="header-anchor" href="#阶段-2-巩固基础" aria-label="Permalink to &quot;阶段 2：巩固基础&quot;">​</a></h2><p>注意！如果你时间不够‌‌‌‌（比如只有 6 个月左右），只是想快速⁢⁢⁢⁢找到工作，那么本阶段甚至可以完全跳过，⁡⁡⁡⁡先去学习开发框架做项目，后面再慢慢弥补基础即可。但如果你时间充裕，或者目标是⁠⁠⁠⁠大厂，建议好好学这个阶段的内容。</p><h3 id="目标-1" tabindex="-1">目标 <a class="header-anchor" href="#目标-1" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>想学好编程‌‌‌‌，计算机基础知识⁢⁢⁢要学⁢好。虽然短期⁡⁡⁡内看⁡不出效果，但长期来看，基础扎⁠⁠⁠实的人走得更⁠远、更稳。</p><p>比如算法，是程‌‌‌‌序员的灵魂。学好算法有助于我⁢⁢⁢⁢们理解程序、开拓思路，因此也⁡⁡⁡⁡是很多公司（尤其是大厂）面试时考察的关键。在找工作前，刷⁠⁠⁠⁠个上百道算法题目是很有必要的。</p><p>我们这个阶段的目标是：</p><ol><li>熟练使用 Java 语言来编写程序，巩固 Java 基础（直接用 Java 来写算法题目，一举两得，岂不美哉？）</li><li>了解计算机基础知识，为后续学习打好基础</li></ol><p>此外，建议大家利用零碎时间多去了解 <strong>计算机基础知识</strong> ，比如操作系统、计算机网络等。虽然这些知识短期内可能用不上，但对你后面学习开发框架、理解系统架构都有很大帮助。我当时就是因为计算机基础学得比较扎实，学框架的时候理解起来特别快。</p><h3 id="java-基础-30-天" tabindex="-1">Java 基础（30 天） <a class="header-anchor" href="#java-基础-30-天" aria-label="Permalink to &quot;Java 基础（30 天）&quot;">​</a></h3><h4 id="学习建议-2" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-2" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>建议大家去阅‌‌‌‌读 《Java 核心技术⁢⁢⁢⁢卷 1》，这本书堪称经典⁡⁡⁡⁡，是帮助你复习巩固 Java 的不二之选，其中⁠⁠⁠⁠图形界面章节可以选择不看。</p><p>之后可以刷网上免费的‌‌‌‌ Java 练习题，检验自己的水平，我当⁢⁢⁢⁢时刷了两遍 1000 题（每天 30 题⁡⁡⁡⁡，1 个月也就刷完了，二刷会更快！）。虽然都是选择题，但能学到很多 Java 语⁠⁠⁠⁠言的特性、避免写代码时容易犯的错误。</p><h4 id="资源-2" tabindex="-1">资源 <a class="header-anchor" href="#资源-2" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.aliyundrive.com/s/SNdB6gr1Xz4" target="_blank" rel="noreferrer">《Java 核心技术卷 1》</a> ：提取码: u74e，经典书籍，必读</li></ul><h3 id="🌖-数据结构和算法" tabindex="-1">🌖 数据结构和算法 <a class="header-anchor" href="#🌖-数据结构和算法" aria-label="Permalink to &quot;🌖 数据结构和算法&quot;">​</a></h3><p>数据结构和算法是程序员的基本功，也是大厂面试的必考内容。</p><p>详细的数据结构和算法学习路线请参考： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789191067892948993?type=" target="_blank" rel="noreferrer">数据结构和算法学习路线</a></p><p>建议结合鱼皮的 <a href="https://algo.codefather.cn/" target="_blank" rel="noreferrer">算法学习动画教程</a> 进行学习，用动画的方式讲解算法，通俗易懂。</p><p><img src="https://pic.code-nav.cn/migrate_image/da16ef3276ae3a43a4743aa726389c62.webp" alt=""></p><h3 id="🌘-计算机导论" tabindex="-1">🌘 计算机导论 <a class="header-anchor" href="#🌘-计算机导论" aria-label="Permalink to &quot;🌘 计算机导论&quot;">​</a></h3><p>详情请参考： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789191099081793538?type=" target="_blank" rel="noreferrer">计算机基础学习路线</a></p><h4 id="知识-2" tabindex="-1">知识 <a class="header-anchor" href="#知识-2" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>计算机发展历史</li><li>计算机应用领域</li><li>计算机发展方向</li><li>计算机基本组成</li><li>二进制</li><li>编程语言发展</li></ul><h4 id="学习建议-3" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-3" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>大学计算机专业的‌‌‌‌同学一般刚开学就会上这门课，虽⁢⁢⁢⁢说学习它并不会直接提高你的编程⁡⁡⁡⁡技能，但能够让你更了解计算机和编程，从而在一定程度上帮助你培⁠⁠⁠⁠养学习兴趣、确定学习方向。</p><p>自学的话，‌‌‌‌不用刻意去学习计⁢⁢⁢算⁢机导论，而是可⁡⁡⁡以通⁡过看视频、阅读课外读物的方式⁠⁠⁠慢慢地了⁠解计算机的故事。</p><h4 id="资源-3" tabindex="-1">资源 <a class="header-anchor" href="#资源-3" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1EW411u7th" target="_blank" rel="noreferrer">《计算机科学速成课》</a> ：从底层到上层的计算机知识科普，强烈推荐）</li><li><a href="https://book.douban.com/subject/35619441/" target="_blank" rel="noreferrer">《半小时漫画计算机》</a> ：轻松有趣的计算机入门书</li></ul><h3 id="🌖-操作系统" tabindex="-1">🌖 操作系统 <a class="header-anchor" href="#🌖-操作系统" aria-label="Permalink to &quot;🌖 操作系统&quot;">​</a></h3><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190984099143681?type=" target="_blank" rel="noreferrer">操作系统学习路线</a></p><h4 id="知识-3" tabindex="-1">知识 <a class="header-anchor" href="#知识-3" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>操作系统的组成</li><li>进程、线程</li><li>进程 / 线程间通讯方式</li><li>进程调度算法</li><li>进程 / 线程同步方式</li><li>进程 / 线程状态</li><li>死锁</li><li>内存管理</li><li>局部性原理</li></ul><h4 id="学习建议-4" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-4" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>说实话，操‌‌‌‌作系统这一块知识挺⁢⁢⁢枯燥⁢的。你说说我现⁡⁡⁡⁡在项目都不会做，你又让我看这些理论，⁠⁠⁠⁠是不是想让我头秃？</p><p>我的建议是，可以‌‌‌‌先利用课余时间看一些网课或者有趣⁢⁢⁢⁢的课外书，对一些操作系统的概念先⁡⁡⁡⁡有个大致的印象，比如进程、线程、死锁，等后面有时间了再系统学习、⁠⁠⁠⁠等到找工作了再去背相关八股文。</p><p>还在校园就跟着学‌‌‌‌校的进度学习就成，自学的话可以⁢⁢⁢⁢看下《清华操作系统原理》视频，⁡⁡⁡⁡有实力的小伙伴，能看懂大黑书就更好了，但如果看不懂也别担心，⁠⁠⁠⁠这并不影响你后续知识的学习。</p><h4 id="经典面试题-2" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-2" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>什么是死锁？死锁产生的条件？</li><li>线程有哪几种状态？</li><li>有哪些进程调度算法？</li><li>什么是缓冲区溢出？</li></ol><h4 id="资源-4" tabindex="-1">资源 <a class="header-anchor" href="#资源-4" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li><a href="https://www.bilibili.com/video/BV1uW411f72n" target="_blank" rel="noreferrer">《清华操作系统原理》</a> ：经典课程</li><li>《编码》：深入浅出的好书</li><li>《30 天自制操作系统》：有趣的实践书籍</li><li>《现代操作系统》：难度较大，不推荐新手看</li><li>《深入理解计算机系统》：难度较大，不推荐新手看</li><li>《自己动手写操作系统》：国产好书，网上可以下载</li><li><a href="https://github.com/QSCTech/zju-icicles" target="_blank" rel="noreferrer">浙大操作系统课件</a></li></ul><h3 id="🌖-计算机网络" tabindex="-1">🌖 计算机网络 <a class="header-anchor" href="#🌖-计算机网络" aria-label="Permalink to &quot;🌖 计算机网络&quot;">​</a></h3><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789191030769164289?type=" target="_blank" rel="noreferrer">计算机网络学习路线</a></p><h4 id="知识-4" tabindex="-1">知识 <a class="header-anchor" href="#知识-4" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>网络分层模型</li><li>网络传输过程</li><li>IP、端口</li><li>HTTP / HTTPS 协议</li><li>UDP / TCP 协议</li><li>ARP 地址解析协议</li><li>网络安全</li><li>DNS 域名解析</li></ul><h4 id="学习建议-5" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-5" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>很多学习 Java 开发的同学最后都是从事 <strong>后端开发</strong> 的工作，而计算机网络知识是后端开发的重点。</p><p>和操作系统一样，自学‌‌‌‌网络可能会很枯燥，建议先看有趣的课外书，⁢⁢⁢⁢比如《图解 HTTP》；或者有趣的视频，⁡⁡⁡⁡比如《计算机网络微课堂》。后面要找工作面试前，再重点去背一些八股文就好了。还在学⁠⁠⁠⁠校的同学好好上课一般就没问题。</p><p>学习基础能‌‌‌‌帮助自己今后⁢发⁢展⁢更⁢稳定，⁡且更⁡容易⁡接受⁡新知识，所以请⁠不要相⁠信基⁠础无用论。</p><h4 id="经典面试题-3" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-3" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>计算机网络各层有哪些协议？</li><li>TCP 和 UDP 协议的区别？</li><li>TCP 为什么需要三次握手和四次挥手？</li><li>HTTP 和 HTTPS 协议的区别？</li></ol><h4 id="资源-5" tabindex="-1">资源 <a class="header-anchor" href="#资源-5" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li><a href="https://www.bilibili.com/video/BV1c4411d7jb" target="_blank" rel="noreferrer">《计算机网络微课堂》</a> ：生动有趣的网络课程</li><li>⭐ 《图解 HTTP》：经典入门书籍</li><li>《网络是怎样连接的》：通俗易懂</li><li>⭐ 《图解 TCP / IP》：深入理解网络协议</li><li><a href="https://github.com/QSCTech/zju-icicles" target="_blank" rel="noreferrer">浙大计算机网络课件</a></li></ul><h3 id="尾声-1" tabindex="-1">尾声 <a class="header-anchor" href="#尾声-1" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>巩固基础要花‌‌‌‌至少 1 个月的时间，当⁢⁢⁢⁢你读完《Java 核心技⁡⁡⁡⁡术卷1》并且不用查询文档也能熟练地用 Java ⁠⁠⁠⁠做题时，就可以接着往下了。</p><h2 id="阶段-3-企业开发基础" tabindex="-1">阶段 3：企业开发基础 <a class="header-anchor" href="#阶段-3-企业开发基础" aria-label="Permalink to &quot;阶段 3：企业开发基础&quot;">​</a></h2><h3 id="目标-2" tabindex="-1">目标 <a class="header-anchor" href="#目标-2" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>面向薪资编程，学习实际后台开发工作要用的基础技术和框架，并能 <strong>独立</strong> 做出一个具有完整功能的 Java Web 项目。</p><p>这个阶段是从 ‌‌‌‌&quot;初学者&quot; 到 &quot;开发者&quot; ⁢⁢⁢⁢的关键转变，学完这个阶段后，⁡⁡⁡⁡你应该已经能独立开发出大多数常见的后台系统了，比如各种管⁠⁠⁠⁠理系统、商城系统、博客网站等。</p><h3 id="🌕-mysql-数据库-7-天" tabindex="-1">🌕 MySQL 数据库（7 天） <a class="header-anchor" href="#🌕-mysql-数据库-7-天" aria-label="Permalink to &quot;🌕 MySQL 数据库（7 天）&quot;">​</a></h3><p>⭐️ 推荐观看 <a href="https://www.bilibili.com/video/BV1iJSLBbEyD/" target="_blank" rel="noreferrer">鱼皮的 MySQL 数据库导学视频</a> ，快速了解 MySQL 数据库学习路线和关键知识。</p><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190581420793858?type=" target="_blank" rel="noreferrer">数据库学习路线</a></p><p>企业中大部分‌‌‌‌业务数据都是用关系型数据⁢⁢⁢⁢库存储的，因此数据库是后⁡⁡⁡⁡台开发同学的必备技能，其中 MySQL 数据库是⁠⁠⁠⁠目前的主流，也是面试时的重点。</p><h4 id="知识-5" tabindex="-1">知识 <a class="header-anchor" href="#知识-5" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>基本概念</li><li>MySQL 搭建</li><li><strong>SQL 语句编写【必学】</strong><ul><li>DDL（数据定义语言） <ul><li>DML（数据操作语言）</li><li>DQL（数据查询语言）</li><li>DCL（数据控制语言）</li></ul></li></ul></li><li>约束 <ul><li>主键约束 <ul><li>外键约束</li><li>唯一约束</li><li>非空约束</li></ul></li></ul></li><li><strong>索引【必学】</strong><ul><li>索引类型 <ul><li>索引原理</li><li>索引优化</li></ul></li></ul></li><li><strong>事务【必学】</strong><ul><li>ACID 特性 <ul><li>隔离级别</li></ul></li></ul></li><li><strong>锁机制【建议学】</strong><ul><li>行锁 / 表锁 <ul><li>乐观锁 / 悲观锁</li></ul></li></ul></li><li><strong>设计数据库表【必学】</strong><ul><li>三大范式 <ul><li>表关联设计</li></ul></li></ul></li><li>性能优化【建议学】</li></ul><h4 id="学习建议-6" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-6" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>数据库是后端开发的基石，一定要学扎实！其中， <strong>SQL 语句编写</strong> 和 <strong>设计数据库表</strong> 这两个能力一定要有！</p><p>比如让你做一个学生‌‌‌‌管理系统，你要能想到需要哪些表，比⁢⁢⁢⁢如学生表、班级表；每个表需要哪些字⁡⁡⁡⁡段、字段类型；表之间是什么关系（一对多、多对多）。这些看似简单，但很⁠⁠⁠⁠多同学在实际做项目时就懵了。</p><p>建议结合鱼皮的 <a href="http://sqlmother.yupi.icu/" target="_blank" rel="noreferrer">SQL 自学网</a> 多写 SQL、多练习，熟能生巧。看完视频后，一定要自己动手设计几个数据库表，比如设计一个博客系统、设计一个电商系统的库表结构。</p><p><img src="https://pic.code-nav.cn/migrate_image/ada6c9f423b275182a8f7c20c5070824.webp" alt=""></p><p>记不住 SQ‌‌‌‌L 语法很正常，用的时候⁢⁢⁢⁢查文档就行，但是一定要理⁡⁡⁡⁡解 SQL 的执行逻辑，理解索引、事务这些核心概⁠⁠⁠⁠念，这些在面试时经常会被问到。</p><h4 id="经典面试题-4" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-4" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>MySQL 索引的最左原则</li><li>InnoDB 和 MyIsam 引擎的区别？</li><li>有哪些优化数据库性能的方法？</li><li>如何定位慢查询？</li><li>MySQL 支持行锁还是表锁？分别有哪些优缺点？</li></ol><h4 id="资源-6" tabindex="-1">资源 <a class="header-anchor" href="#资源-6" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1Kr4y1i7ru" target="_blank" rel="noreferrer">2024 黑马 MySQL 教程</a> ：倾向于速成，初学只看完 P57 节前的基础篇即可</li><li><a href="https://www.bilibili.com/video/BV1xW411u7ax" target="_blank" rel="noreferrer">尚硅谷 - MySQL 基础教程</a> ：小姐姐讲课</li><li>⭐ <a href="http://sqlmother.yupi.icu/" target="_blank" rel="noreferrer">鱼皮的闯关式 SQL 自学网</a> ：强烈推荐，边玩边学</li><li><a href="https://www.bejson.com/runcode/sql/" target="_blank" rel="noreferrer">SQL 在线运行</a></li></ul><h3 id="🌕-开发框架-60-天" tabindex="-1">🌕 开发框架（60 天） <a class="header-anchor" href="#🌕-开发框架-60-天" aria-label="Permalink to &quot;🌕 开发框架（60 天）&quot;">​</a></h3><p>Java 之所‌‌‌‌以能成为主流的企业开发语言⁢⁢⁢⁢，很大一部分原因是它完善的⁡⁡⁡⁡框架生态，用好框架，不仅能够大大提升开发效率，还能提⁠⁠⁠⁠高项目的稳定性、减少维护成本。</p><p>开发框架是‌‌‌‌后台开发工作⁢中⁢不⁢可⁢或缺的⁡，也⁡是面⁡试考⁡察的重点，一定⁠要好好⁠学！</p><p>不知道 J‌‌‌‌ava 能做⁢什⁢么⁢的⁢朋友们⁡，学⁡完开⁡发框⁡架，就会有答案⁠啦。</p><p>下面给大家‌‌‌‌推荐的都是企业⁢⁢中⁢应⁢用最多的主⁡⁡流开⁡发框⁡架，知识点比较零碎，⁠⁠就放在⁠一起讲了。</p><h4 id="知识-6" tabindex="-1">知识 <a class="header-anchor" href="#知识-6" aria-label="Permalink to &quot;知识&quot;">​</a></h4><h5 id="🌕-java-web" tabindex="-1">🌕 Java Web <a class="header-anchor" href="#🌕-java-web" aria-label="Permalink to &quot;🌕 Java Web&quot;">​</a></h5><ul><li>描述：Java 网页应用开发基础</li><li>一丢丢前端基础</li><li>XML</li><li>JSON</li><li>Servlet</li><li>Filter</li><li>Listener</li><li>JSP</li><li>JSTL</li><li>Cookie</li><li>Session</li></ul><h5 id="🌕-spring-5" tabindex="-1">🌕 Spring 5 <a class="header-anchor" href="#🌕-spring-5" aria-label="Permalink to &quot;🌕 Spring 5&quot;">​</a></h5><ul><li>描述：Java 轻量级应用框架</li><li>IOC</li><li>AOP</li><li>事务</li></ul><h5 id="🌕-springmvc" tabindex="-1">🌕 SpringMVC <a class="header-anchor" href="#🌕-springmvc" aria-label="Permalink to &quot;🌕 SpringMVC&quot;">​</a></h5><ul><li>描述：Java 轻量级 web 开发框架</li><li>什么是 MVC？</li><li>请求和响应</li><li>Restful API</li><li>拦截器</li><li>配置</li><li>执行过程</li></ul><h5 id="🌕-mybatis" tabindex="-1">🌕 MyBatis <a class="header-anchor" href="#🌕-mybatis" aria-label="Permalink to &quot;🌕 MyBatis&quot;">​</a></h5><ul><li>描述：数据访问框架，操作数据库进行增删改查等操作</li><li>增删改查</li><li>全局配置</li><li>动态 SQL</li><li>缓存</li><li>和其他框架的整合</li><li>逆向工程</li></ul><h5 id="🌗-mybatis-plus" tabindex="-1">🌗 MyBatis Plus <a class="header-anchor" href="#🌗-mybatis-plus" aria-label="Permalink to &quot;🌗 MyBatis Plus&quot;">​</a></h5><ul><li>描述：Mybatis 的增强工具，能够简化开发、提高效率</li><li>引入</li><li>通用 CRUD</li><li>条件构造器</li><li>代码生成器</li><li>插件扩展</li><li>自定义全局操作</li></ul><h5 id="🌕-springboot-2" tabindex="-1">🌕 SpringBoot 2 <a class="header-anchor" href="#🌕-springboot-2" aria-label="Permalink to &quot;🌕 SpringBoot 2&quot;">​</a></h5><ul><li>描述：简化 Spring 应用的初始搭建以及开发过程，提高效率</li><li>常用注解</li><li>资源整合</li><li>高级特性</li><li>本地热部署</li></ul><h5 id="🌗-spring-security" tabindex="-1">🌗 Spring Security <a class="header-anchor" href="#🌗-spring-security" aria-label="Permalink to &quot;🌗 Spring Security&quot;">​</a></h5><ul><li>描述：Spring 的安全管理框架</li><li>用户认证</li><li>权限管理</li><li>相关技术：Shiro</li></ul><h5 id="🌗-maven-gradle" tabindex="-1">🌗 Maven / Gradle <a class="header-anchor" href="#🌗-maven-gradle" aria-label="Permalink to &quot;🌗 Maven / Gradle&quot;">​</a></h5><ul><li>描述：项目管理工具</li><li>构建</li><li>依赖管理</li><li>插件</li><li>配置</li><li>子父工程</li><li>多模块打包构建</li><li>Nexus 私服搭建</li></ul><h4 id="学习建议-7" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-7" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>1）选择同一系列教程：由‌‌‌‌于技术较多，且框架之间存在一定的联系，因此建议大⁢⁢⁢⁢家看同一系列的视频教程（比如都看黑马的，或者都看⁡⁡⁡⁡尚硅谷的），以保证学习内容的连续以及体验上的一致。不要今天看这个老师的 Spring，明天看那个⁠⁠⁠⁠老师的 MyBatis，容易混乱。</p><p>2）多记笔记，多敲代码：学‌‌‌‌这些技术的时候，千万不能懒！一定要多记笔记，并且跟⁢⁢⁢⁢着老师写代码。原理部分不要太过纠结，先以能跟着敲出⁡⁡⁡⁡代码、写出可运行的项目为主，有些东西做出来也能帮助你更好地理解理论。我的建议是，视频倍速播放，但是代⁠⁠⁠⁠码一定要一行一行手敲，不要复制粘贴。</p><p>3）注意学习顺序：学习顺序挺重要的，建议按我推荐的顺序学，不要一上手就学 Spring Boot。只有先学习下自己整合框架的方法（比如手动配置 Spring + MyBatis），才能帮你理解 SpringBoot 解决的问题，感受到它的方便和高效。这样学下来，面试的时候也能说出个所以然来。</p><p>4）框架会用就行：‌‌‌‌Maven / Gradle 当成⁢⁢⁢⁢工具用就好，面试基本不问，跟着框架⁡⁡⁡⁡教程去用就行了，急着找工作的话，先不用花太多时间去深入学。大厂面试问⁠⁠⁠⁠这个的也不多，会配置、会用就够了。</p><h4 id="经典面试题-5" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-5" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>Spring 的 IOC 和 AOP 是什么，有哪些优点？</li><li>Spring 框架用到了哪些设计模式？</li><li>介绍 Spring Bean 的生命周期</li><li>MyBatis 如何实现延迟加载？</li><li>介绍 MyBatis 的多级缓存机制</li></ol><p>更多框架面试题：</p><ul><li><a href="https://www.mianshiya.com/bank/1790683494127804418" target="_blank" rel="noreferrer">Spring 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1797452903309508610" target="_blank" rel="noreferrer">SpringBoot 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1801424748099739650" target="_blank" rel="noreferrer">MyBatis 面试题 - 面试鸭</a></li></ul><h4 id="资源-7" tabindex="-1">资源 <a class="header-anchor" href="#资源-7" aria-label="Permalink to &quot;资源&quot;">​</a></h4><p>下面的资源分‌‌‌‌为两大类，希望快速做出⁢⁢⁢⁢项目、快速就业的同学请⁡⁡⁡⁡看【速成视频】；想要系统学习、打好基础的同学⁠⁠⁠⁠可以看【非速成视频】。</p><p><strong>速成视频（按顺序看，同类视频任意选择 1 个即可）：</strong></p><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1m84y1w7Tb" target="_blank" rel="noreferrer">2024 黑马 JavaWeb</a> ：包含前端、MySQL、Java Web、MyBatis、Spring MVC、Spring、Spring Boot、Maven 等知识，内容很新很全面</li><li><a href="https://www.bilibili.com/video/BV1Ya411S7aT" target="_blank" rel="noreferrer">2024 尚硅谷 SSM + MyBatis Plus 整合学习</a> ：比较系统地讲解了 SSM 框架的整合</li><li><a href="https://www.bilibili.com/video/BV15b4y1a7yG" target="_blank" rel="noreferrer">黑马 Spring Boot 2</a> ：讲解 SpringBoot 核心特性</li><li><a href="https://www.bilibili.com/video/BV19K4y1L7MT" target="_blank" rel="noreferrer">尚硅谷 Spring Boot 2</a> ：内容全面，讲得很细</li></ul><p><strong>非速成视频（按顺序看）：</strong></p><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1Y7411K7zz" target="_blank" rel="noreferrer">尚硅谷 JavaWeb 全套教程</a> ：前端部分最好也看下，虽然有点老但基础讲得很扎实</li><li>⭐ <a href="https://www.bilibili.com/video/BV1Vf4y127N5" target="_blank" rel="noreferrer">尚硅谷 - Spring 5 框架最新版教程（IDEA 版）</a> ：系统讲解 Spring 核心思想</li><li>⭐ <a href="https://www.bilibili.com/video/BV1Ry4y1574R" target="_blank" rel="noreferrer">尚硅谷 - SpringMVC 2021 最新教程</a> ：MVC 架构讲得很清楚</li><li>⭐ <a href="https://www.bilibili.com/video/BV1mW411M737" target="_blank" rel="noreferrer">尚硅谷 - MyBatis 实战教程全套完整版</a> ：经典教程，讲得很细</li><li>⭐ <a href="https://www.bilibili.com/video/BV1Ds411E76Y" target="_blank" rel="noreferrer">尚硅谷 - MyBatisPlus 教程</a> ：提高开发效率必学</li><li><a href="https://www.bilibili.com/video/BV1TW411g7hP" target="_blank" rel="noreferrer">Maven 零基础入门教程</a> ：搞不懂 Maven 可以看看</li><li>⭐ <a href="https://www.bilibili.com/video/BV19K4y1L7MT" target="_blank" rel="noreferrer">雷丰阳 2021 版 SpringBoot2 零基础入门</a> ：讲得非常细致全面</li><li><a href="https://www.bilibili.com/video/BV15a411A7kP" target="_blank" rel="noreferrer">尚硅谷 - SpringSecurity 框架教程</a> ：权限框架必学</li></ul><p>学习完框架后，即可跟着鱼皮的原创项目教程系列边学边做项目。用项目驱动学习，更快地掌握后端必学技术，并直接写在简历上： <a href="https://www.codefather.cn/post/1797431216467001345" target="_blank" rel="noreferrer">项目实战 - 鱼皮原创项目教程系列</a> 。</p><h3 id="🌘-开发规范-3-天" tabindex="-1">🌘 开发规范（3 天） <a class="header-anchor" href="#🌘-开发规范-3-天" aria-label="Permalink to &quot;🌘 开发规范（3 天）&quot;">​</a></h3><p>开发不规范‌‌，同事两行泪。 ⁢ ⁢       ⁡  ⁡              ⁠    ⁠</p><p>开发规范是‌‌‌‌团队开发中必须⁢遵⁢守⁢的，有⁢利于⁡提高⁡项目⁡的开发效率⁡、降低维⁠护成本。                   ⁠</p><h4 id="知识-7" tabindex="-1">知识 <a class="header-anchor" href="#知识-7" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>代码规范 <ul><li>代码风格 <ul><li>命名</li><li>其他规则</li></ul></li></ul></li><li>代码校验（CheckStyle）</li><li>提交规范</li></ul><h4 id="学习建议-8" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-8" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>有时间的话，‌‌‌‌简单过一遍大厂团队的代⁢⁢⁢⁢码规范手册就好了，以后⁡⁡⁡⁡做项目的时候能想起来的话就去使用，或者从书中⁠⁠⁠⁠、网上查规范文档，再去遵守。</p><p>项目做得多了，自‌‌‌‌然会养成好的习惯，不用刻意去记⁢⁢⁢⁢（毕竟每个团队规范也不完全相同⁡⁡⁡⁡，背了也没用）。也可以直接利用开发工具自带的一些代码检查插件⁠⁠⁠⁠，帮忙养成好的编码习惯。</p><h4 id="资源-8" tabindex="-1">资源 <a class="header-anchor" href="#资源-8" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://developer.aliyun.com/graph/java" target="_blank" rel="noreferrer">阿里巴巴 Java 开发手册</a> ：搜索《Java开发手册》，阿里官方代码规范</li><li><a href="https://developer.aliyun.com/live/1201" target="_blank" rel="noreferrer">华山版《Java开发手册》独家讲解</a> ：视频讲解</li><li><a href="https://google.github.io/styleguide/javaguide.html" target="_blank" rel="noreferrer">Google Java Style Guide</a> ：谷歌 Java 代码规范</li></ul><h3 id="🌕-git-3-天" tabindex="-1">🌕 Git（3 天） <a class="header-anchor" href="#🌕-git-3-天" aria-label="Permalink to &quot;🌕 Git（3 天）&quot;">​</a></h3><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190804671012866?type=" target="_blank" rel="noreferrer">Git &amp; GitHub 学习路线</a></p><p>此前大家可能听说过 GitHub，一流的代码开源托管平台。</p><p>Git 和它‌‌‌‌可不一样，是一个版本控⁢⁢⁢⁢制工具，可以更好地管理⁡⁡⁡⁡和共享项目代码，比如把自己的代码传到 Git⁠⁠⁠⁠Hub 上、或者从远程下载。</p><p>无论自己做‌‌‌‌项目、还是团⁢队⁢开⁢发⁢，Gi⁡t ⁡都是⁡现在⁡不可或缺的神器⁠。</p><h4 id="知识-8" tabindex="-1">知识 <a class="header-anchor" href="#知识-8" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>区分 Git 和 GitHub</li><li>工作区</li><li>分支</li><li>代码提交、推送、拉取、回退、重置</li><li>分支操作</li><li>代码合并、解决冲突</li><li>标签</li><li>cherry-pick</li><li>Git Flow</li><li>相关技术：SVN（比较老）</li></ul><h4 id="学习建议-9" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-9" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>每个命令跟着敲一遍，有个大致的印象，会用即可。</p><p>建议平时大‌‌‌‌家可以多把自己的⁢⁢⁢代⁢码使用 Git⁡⁡⁡ 命⁡令上传到 GitHub 上，⁠⁠⁠用的多了自然⁠就熟悉了。</p><h4 id="经典面试题-6" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-6" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>如何解决提交冲突？</li><li>提交不小心出现误操作，如何撤销？</li><li>什么是 Git Flow，它有什么好处？</li></ol><h4 id="资源-9" tabindex="-1">资源 <a class="header-anchor" href="#资源-9" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1vy4y1s7k6" target="_blank" rel="noreferrer">尚硅谷 - 5h 打通 Git 全套教程丨2021 最新 IDEA 版</a></li><li><a href="https://backlog.com/git-tutorial/cn/" target="_blank" rel="noreferrer">猴子都能懂的 Git 入门</a> （图文并茂，适合入门）</li><li>⭐ <a href="https://github.phodal.com/" target="_blank" rel="noreferrer">GitHub 漫游指南</a> （GitHub 使用指南）</li><li><a href="https://docs.github.com/cn" target="_blank" rel="noreferrer">GitHub 官方文档</a></li><li><a href="https://learngitbranching.js.org/?locale=zh_CN" target="_blank" rel="noreferrer">Learning Git Branching</a> （游戏化学习 Git）</li></ul><h3 id="🌖-linux-10-天" tabindex="-1">🌖 Linux（10 天） <a class="header-anchor" href="#🌖-linux-10-天" aria-label="Permalink to &quot;🌖 Linux（10 天）&quot;">​</a></h3><p>⭐️ 建议先观看 <a href="https://www.bilibili.com/video/BV1ev411G7VE/" target="_blank" rel="noreferrer">鱼皮的 Linux 导学视频</a> ，快速了解 Linux 学习路线和关键知识</p><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190769740849154?type=" target="_blank" rel="noreferrer">Linux 学习路线</a></p><p>企业中的很‌‌‌‌多前后台项目都是部⁢⁢⁢⁢署在 Linux ⁡⁡⁡⁡服务器上的，因此很有必要熟悉 Lin⁠⁠⁠⁠ux 的操作和脚本的编写。</p><p>后面学微服‌‌‌‌务、学架构都⁢是⁢在⁢多⁢台服务⁡器操⁡作，⁡如果⁡你不熟悉 Li⁠nux⁠，会⁠有点吃力。</p><h4 id="知识-9" tabindex="-1">知识 <a class="header-anchor" href="#知识-9" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>Linux 系统安装</li><li>环境变量</li><li>文件管理</li><li>用户管理</li><li>内存管理</li><li>磁盘管理</li><li>进程管理</li><li>网络管理</li><li>软件包管理</li><li>服务管理</li><li>日志管理</li><li>Linux 内核</li><li><strong>常用命令</strong></li><li><strong>常用环境搭建</strong></li><li><strong>Shell 脚本编程</strong></li><li><strong>VIM 的使用</strong></li></ul><h4 id="学习建议-10" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-10" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>Linux‌‌‌‌ 是后端开发必⁢⁢备⁢技⁢能，因为企⁡⁡业中⁡的项⁡目基本都是部署在 L⁠⁠inux⁠ 服⁠务器上的。</p><p>1）动手实践最重要‌‌‌‌：建议自己购买一台云服务器（阿里云、⁢⁢⁢⁢腾讯云学生机一年才几十块钱），并且在⁡⁡⁡⁡本地用 VMware 搭建 Linux 虚拟机环境。光看视频是学不会 L⁠⁠⁠⁠inux 的，一定要自己敲命令！</p><p>2）从零开始部署项目：‌‌‌‌看完基础教程后，一定要自己从 0 开始手敲命⁢⁢⁢⁢令安装软件（比如 MySQL、Redis、N⁡⁡⁡⁡ginx）、部署服务，熟悉整个项目的上线流程。第一次部署肯定会遇到各种问题，这很正常，解⁠⁠⁠⁠决问题的过程就是最好的学习过程。</p><p>3）常用命令要熟悉：每‌‌‌‌个命令至少要跟着敲一遍，了解它们的作用，并通⁢⁢⁢⁢过自然地练习，熟悉常用的 Linux 命令（⁡⁡⁡⁡cd、ls、cat、grep、ps、top、vi 等）。记不住没关系，用的时候查文档就行⁠⁠⁠⁠，但是一些高频命令要做到能随手写出来。</p><p>4）先会用，再理解：不要一上‌‌‌‌来就去研究 Linux 内核，那样会把自己绕晕。先会用，⁢⁢⁢⁢能用 Linux 部署项目、排查问题就行。一般面试问的 ⁡⁡⁡⁡Linux 题目也不会很难，主要考察常用命令和基本概念，面试前去背一下八股文就没什么问题。等工作后有需要了，再去⁠⁠⁠⁠深入学习 Linux 内核设计也不迟。</p><h4 id="经典面试题-7" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-7" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>如何查看某个进程的运行状态？</li><li>如何在 Linux 上查看 2 G 的大文件？</li><li>Linux 软链接和硬链接的区别</li></ol><h4 id="资源-10" tabindex="-1">资源 <a class="header-anchor" href="#资源-10" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1Sv411r7vd" target="_blank" rel="noreferrer">2021 韩顺平 - 一周学会 Linux</a> ：基于 CentOS 7.6 版本</li><li><a href="http://cn.linux.vbird.org/linux_basic/linux_basic.php" target="_blank" rel="noreferrer">《鸟哥的 Linux 私房菜 —— 基础篇》</a> ：经典教材，可在线阅读</li><li><a href="https://linuxtools-rst.readthedocs.io/" target="_blank" rel="noreferrer">Linux 工具快速教程</a> ：基础、工具进阶、工具参考</li><li>⭐ <a href="https://www.lanqiao.cn/courses/1" target="_blank" rel="noreferrer">蓝桥云课 - Linux 基础入门</a> ：在线实战环境</li><li><a href="https://cloud.tencent.com/developer/labs" target="_blank" rel="noreferrer">腾讯云动手实验室</a></li><li><a href="https://developer.aliyun.com/adc/labs/" target="_blank" rel="noreferrer">阿里云体验实验室</a></li><li><a href="https://lab.huaweicloud.com/" target="_blank" rel="noreferrer">华为云沙箱实验室</a></li><li>⭐ <a href="https://wangchujiang.com/linux-command" target="_blank" rel="noreferrer">Linux 命令搜索</a> ：命令速查必备</li><li><a href="https://www.linuxcool.com/" target="_blank" rel="noreferrer">Linux 命令大全手册</a></li><li><a href="https://www.bt.cn/" target="_blank" rel="noreferrer">宝塔 Linux 面板</a> ：可视化服务器管理</li></ul><h3 id="🌘-前端基础-14-天" tabindex="-1">🌘 前端基础（14 天） <a class="header-anchor" href="#🌘-前端基础-14-天" aria-label="Permalink to &quot;🌘 前端基础（14 天）&quot;">​</a></h3><p>详情请参考鱼皮原创的 <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190394078011393" target="_blank" rel="noreferrer">保姆级前端学习路线</a> 。</p><p>虽然 Java 程序员‌‌‌‌面试时基本不会出现前端相关问题，但是在企业中⁢⁢⁢⁢，往往需要前后端程序员配合完成工作。会一些前⁡⁡⁡⁡端，不仅可以提高你们的协作效率，还能提高自己对整个项目的了解和掌控力，甚至能独立开发出一⁠⁠⁠⁠个完整项目！这点也是能给面试加分的。</p><h4 id="知识-10" tabindex="-1">知识 <a class="header-anchor" href="#知识-10" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>HTML</li><li>CSS</li><li>JavaScript <ul><li>Ajax</li></ul></li><li>Vue</li></ul><h4 id="学习建议-11" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-11" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>作为 Ja‌‌‌‌va 后端开发，⁢⁢⁢不⁢需要学习太深的⁡⁡⁡前端⁡技术，但是了解一些基础的前端⁠⁠⁠知识还是很⁠有必要的。</p><p>1）学到什么程度：‌‌‌‌熟悉下基础的前端三件套（HTML、C⁢⁢⁢⁢SS、JavaScript），了解前⁡⁡⁡⁡端是如何向后端发送请求（Ajax）来做数据交互的，一般就够了。不需要深入⁠⁠⁠⁠学习各种前端框架和工程化工具。</p><p>2）建议学 Vue：有时间的话可以学下 Vue，是比较容易上手的主流前端开发框架。学会了 Vue，你就能独立开发一个前后端分离的完整项目，Vue + SpringBoot 的组合还是很香的。而且简历上能写 &quot;全栈开发&quot; 也更有竞争力。</p><p>3）跟着项目学‌‌‌‌：推荐跟着鱼皮的原创项目教⁢⁢⁢⁢程系列学习前端，每个项目都⁡⁡⁡⁡是前端 + 后端的全栈项目，边做项目边学前端，比单独⁠⁠⁠⁠看前端教程效果好很多。</p><p>4）善用 AI：AI 时代学习前端更简单了！可以让 AI 帮你生成前端代码、解释前端概念、修复 Bug。推荐跟着鱼皮的 <a href="https://www.codefather.cn/course/1965699176489484289" target="_blank" rel="noreferrer">AI 程序员技术练兵场项目</a> 学习如何用 AI 辅助前端开发，能让你的开发效率翻倍。</p><h3 id="练手项目-1" tabindex="-1">练手项目 <a class="header-anchor" href="#练手项目-1" aria-label="Permalink to &quot;练手项目&quot;">​</a></h3><p>推荐跟着鱼皮的原创项目教程系列边学边做项目，每个项目都是前端 + 后端的全栈项目。用项目驱动学习，更快掌握前端基础和后端必学技术，并直接写在简历上： <a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">项目实战 - 鱼皮原创项目教程系列</a> 。</p><p><strong>AI 应用开发：</strong></p><p>当前 AI 应用开发‌‌‌‌已成为最热门的技术方向之一！建议在学习⁢⁢⁢⁢传统项目的同时，尝试将 AI 能力融入⁡⁡⁡⁡到你的项目中。比如在管理系统中加入智能推荐、自动生成报表、AI 客服等功能，⁠⁠⁠⁠这类项目在求职时会非常加分。</p><p>强烈推荐学习‌鱼皮的‌‌‌ AI 应用开发⁢系列项目，能够快速掌⁢⁢⁢握⁡ LangChain4j、Spr⁡⁡⁡ing AI⁠ 等主流 AI 开发框架：                  ⁠⁠⁠</p><ul><li><a href="https://www.codefather.cn/course/1943267371799080961" target="_blank" rel="noreferrer">AI 编程助手</a> ：适合新手入门 AI 应用开发，实战 LangChain4j 框架</li><li><a href="https://www.codefather.cn/course/1965699176489484289" target="_blank" rel="noreferrer">AI 程序员技术练兵场</a> ：以 AI 编程为主的 Java + Vue 全栈 AI 应用开发教程</li><li><a href="https://www.codefather.cn/course/1948291549923344386" target="_blank" rel="noreferrer">AI 零代码应用生成平台</a> ：对标大厂的微服务 AI 项目，实战 AI 智能体、LangGraph4j 工作流、微服务架构</li><li><a href="https://www.codefather.cn/course/1915010091721236482" target="_blank" rel="noreferrer">AI 超级智能体项目</a> ：学习实践 AI 应用开发，掌握新时代程序员必知的 AI 技术</li></ul><p><strong>其他开源项目：</strong></p><ul><li>HotelSystem： <a href="https://github.com/misterchaos/HotelSystem" target="_blank" rel="noreferrer">https://github.com/misterchaos/HotelSystem</a> （酒店管理系统 Java,tomcat,mysql,servlet,jsp实现，没有使用任何框架）</li><li>超市管理系统： <a href="https://github.com/zhanglei-workspace/shopping-management-system" target="_blank" rel="noreferrer">https://github.com/zhanglei-workspace/shopping-management-system</a></li><li>Mall4j： <a href="https://github.com/gz-yami/mall4j" target="_blank" rel="noreferrer">https://github.com/gz-yami/mall4j</a> （Spring Boot 电商系统）</li><li>newbee-mall： <a href="https://github.com/newbee-ltd/newbee-mall" target="_blank" rel="noreferrer">https://github.com/newbee-ltd/newbee-mall</a> （基于 Spring Boot 2.X 的全栈电商系统）</li><li>litemall： <a href="https://github.com/linlinjava/litemall" target="_blank" rel="noreferrer">https://github.com/linlinjava/litemall</a> （小商城系统，Spring Boot 后端 + Vue 管理员前端 + 微信小程序用户前端 + Vue 用户移动端）</li><li>forum-java： <a href="https://github.com/Qbian61/forum-java" target="_blank" rel="noreferrer">https://github.com/Qbian61/forum-java</a> （一款用 Java Spring Boot 实现的现代化社区系统）</li></ul><h3 id="尾声-2" tabindex="-1">尾声 <a class="header-anchor" href="#尾声-2" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>学完这个阶段的知识‌‌‌‌后，一定要再串起来回忆一遍，必须自己⁢⁢⁢⁢独立开发一个 Java Web 项目⁡⁡⁡⁡（量级可以不大，但你学过的技术尽可能地用上），能发布到 Linux 服务⁠⁠⁠⁠器上让其他小伙伴访问就更好了~</p><p>在 AI 时代，建议大家在掌握基础开发能力后，尽早开始学习 AI 应用开发！现在 AI 应用开发已经成为热门方向，很多企业都在招聘懂 AI 的 Java 开发工程师。建议在做项目时，尝试融入 AI 能力，比如智能推荐、内容生成、AI 对话等功能。鱼皮的 <a href="https://www.codefather.cn/course/1943267371799080961" target="_blank" rel="noreferrer">AI 编程助手</a> 、 <a href="https://www.codefather.cn/course/1965699176489484289" target="_blank" rel="noreferrer">AI 程序员技术练兵场</a> 等项目都是很好的入门选择，能够帮你快速掌握 Spring AI、LangChain4j 等主流 AI 开发框架。</p><p>如果你只是对 ‌‌‌‌Java 感兴趣、或者只是想⁢⁢⁢⁢试着自己开发后台，并不是想靠⁡⁡⁡⁡ Java 找工作的话，学到这里就可以了。可以把更多时间⁠⁠⁠⁠投入到你主方向的学习中。</p><p>但如果你是‌‌‌‌想找 Java 方向⁢⁢⁢⁢的工作，尤其是想进大⁡⁡⁡⁡厂的话，一定要继续努力，用心学习下个阶段⁠⁠⁠⁠的企业开发进阶知识。</p><h2 id="阶段-4-企业开发进阶" tabindex="-1">阶段 4：企业开发进阶 <a class="header-anchor" href="#阶段-4-企业开发进阶" aria-label="Permalink to &quot;阶段 4：企业开发进阶&quot;">​</a></h2><h3 id="目标-3" tabindex="-1">目标 <a class="header-anchor" href="#目标-3" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>学习更多企业级开发技术和编程思想，能够结合多种技术，独立开发出架构合理的完整系统， <strong>解决实际问题</strong> 。</p><p>前面几个阶段学的技术，‌‌‌‌已经能让你做出一个基本的系统了。但是在实际⁢⁢⁢⁢的企业开发中，我们还会遇到很多问题：系统访⁡⁡⁡⁡问量大了怎么办？如何提高系统性能？如何保证系统的稳定性？多个系统之间如何协作？这个阶⁠⁠⁠⁠段就是要学习解决这些问题的技术。</p><p>要了解为什‌‌‌‌么需要这个技术？⁢⁢⁢什⁢么时候用这个技⁡⁡⁡术？⁡某个需求该用哪些技术？不要为⁠⁠⁠了用技术⁠而用技术。</p><p>当然，这个阶段的内‌‌‌‌容有些过于丰富，不是所有的东西都要⁢⁢⁢⁢学，大家可以根据自己的实际情况（时⁡⁡⁡⁡间、求职紧迫程度），有选择地学习。如果时间紧急，可以先学 Redis⁠⁠⁠⁠ 和微服务，其他的等工作后再补。</p><h3 id="🌘-软件工程" tabindex="-1">🌘 软件工程 <a class="header-anchor" href="#🌘-软件工程" aria-label="Permalink to &quot;🌘 软件工程&quot;">​</a></h3><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190653197918210?type=" target="_blank" rel="noreferrer">软件工程学习路线</a></p><p>软件开发和管理的一些概念、原则、技术、方法、工具和经验。</p><h4 id="知识-11" tabindex="-1">知识 <a class="header-anchor" href="#知识-11" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>软件的本质</li><li>软件特性</li><li>软件过程</li><li>软件开发原则 <ul><li>开闭原则 <ul><li>里氏替换原则</li><li>依赖倒置原则</li><li>单一职责原则</li><li>接口隔离原则</li><li>迪米特法则</li></ul></li></ul></li><li>软件过程模型</li><li>敏捷开发</li><li>软件开发模型</li><li>需求建模</li><li>软件设计</li><li>UML</li><li>体系结构设计</li><li>设计模式</li><li>软件质量管理</li><li>评审</li><li>软件质量保证</li><li>软件测试 <ul><li>单元测试 <ul><li>集成测试</li><li>系统测试</li><li>压力测试</li><li>部署测试</li></ul></li></ul></li><li>软件配置管理</li><li>软件项目管理</li><li>软件项目估算</li><li>项目进度安排</li><li>风险管理</li><li>软件过程改进 <ul><li>成熟度模型</li></ul></li></ul><h4 id="学习建议-12" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-12" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>大学软件专业的必‌‌‌‌修课，偏理论，能学到很多企业软件⁢⁢⁢⁢开发的方法，也是对软件开发同学综⁡⁡⁡⁡合能力的提升，有时间的话可以了解下。但对想要快速找工作的同学来说⁠⁠⁠⁠，忽略即可，面试基本不会问。</p><h4 id="资源-11" tabindex="-1">资源 <a class="header-anchor" href="#资源-11" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li><a href="https://book.douban.com/subject/6047742/" target="_blank" rel="noreferrer">《软件工程：实践者的研究方法》</a> （经典大黑书，讲得非常全面）</li><li><a href="https://book.douban.com/subject/35628886/" target="_blank" rel="noreferrer">《软件开发的 201 个原则》</a> （工具书，看一遍挺好的）</li><li><a href="https://www.bilibili.com/video/BV1Vt411V72G" target="_blank" rel="noreferrer">北京大学软件工程</a> （公开课）</li><li><a href="https://www.bilibili.com/video/BV1Ns41177VM" target="_blank" rel="noreferrer">大连工业大学软件工程</a></li><li><a href="https://github.com/QSCTech/zju-icicles" target="_blank" rel="noreferrer">浙大计算机软件工程课件</a></li></ul><h3 id="🌖-设计模式-21-天" tabindex="-1">🌖 设计模式（21 天） <a class="header-anchor" href="#🌖-设计模式-21-天" aria-label="Permalink to &quot;🌖 设计模式（21 天）&quot;">​</a></h3><p>⭐️ 推荐观看 <a href="https://www.bilibili.com/video/BV1za411p7Ny" target="_blank" rel="noreferrer">鱼皮的设计模式导学视频</a> ，快速掌握设计模式的高效学习法</p><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190698894860290?type=" target="_blank" rel="noreferrer">设计模式学习路线</a></p><p>设计模式是软件开发中解决一类问题的通用方法。</p><p>使用设计模‌式能‌‌‌让你写出更优雅⁢、可维护的代码，⁢⁢⁢也⁡正因如此，很多框架源码都用⁡⁡⁡到了设计模⁠式，你不学很难看懂。                ⁠⁠⁠</p><p>此外，鱼皮改了几百份简历，基本上没有同学把设计模式写在项目经历中。 <strong>因此学好设计模式并写在简历上是很加分的！</strong></p><h4 id="知识-12" tabindex="-1">知识 <a class="header-anchor" href="#知识-12" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>创建型模式：对象实例化的模式，创建型模式用于解耦对象的实例化过程 <ul><li>单例模式 <ul><li>工厂方法模式</li><li>抽象工厂</li><li>建造者模式</li><li>原型模式</li></ul></li></ul></li><li>结构型模式：把类或对象结合在一起形成一个更大的结构 <ul><li>适配器模式 <ul><li>组合模式</li><li>装饰器模式</li><li>代理模式</li><li>享元模式</li><li>外观模式</li><li>桥接模式</li></ul></li></ul></li><li>行为型模式：类和对象如何交互，及划分责任和算法 <ul><li>迭代器模式 <ul><li>模板方法模式</li><li>策略模式</li><li>命令模式</li><li>状态模式</li><li>责任链模式</li><li>备忘录模式</li><li>观察者模式</li><li>访问者模式</li><li>中介者模式</li><li>解释器模式</li></ul></li></ul></li></ul><h4 id="学习建议-13" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-13" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>设计模式是‌‌‌‌个好东西，但⁢是⁢很⁢多⁢同学学⁡完了⁡却不⁡知道⁡怎么用，或者用⁠得不对⁠。</p><p>1）先理解再实践‌‌‌‌：先理解概念，了解每个设计模式的⁢⁢⁢⁢特点和应用场景（解决什么问题、什⁡⁡⁡⁡么时候用），再多加练习，运用到实际项目中。千万不要死记硬背 23⁠⁠⁠⁠ 种设计模式，那样毫无意义。</p><p>2）重点掌握常‌‌‌‌用的：实际工作中，并不是所有⁢⁢⁢⁢的设计模式都会用到。建议重点⁡⁡⁡⁡掌握单例模式、工厂模式、策略模式、模板方法模式、代理模式⁠⁠⁠⁠这几个最常用的，其他的了解即可。</p><p>3）结合项目学习：推荐跟着鱼皮的 <a href="https://www.codefather.cn/course/1790979621621641217" target="_blank" rel="noreferrer">聚合搜索项目</a> 、 <a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统</a> 学习，这两个项目都运用了大量的设计模式（策略模式、工厂模式、模板方法等），能让你理解设计模式在实际项目中是怎么用的。光看书和视频，很难真正理解设计模式的精髓。</p><p>4）写在简历上：鱼皮‌‌‌‌改了几百份简历，基本上没有同学把设计模式⁢⁢⁢⁢写在项目经历中。如果你的项目中用到了设计⁡⁡⁡⁡模式，一定要写在简历上，这是很大的加分项！比如 &quot;使用策略模式 + 工厂模式实现⁠⁠⁠⁠了多种文件上传方式的灵活切换&quot;。</p><h4 id="经典面试题-8" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-8" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>单例模式有哪些实现方式？有哪些优缺点？请手写其中一种</li><li>你用过哪些设计模式，为什么用它？</li><li>工厂模式和抽象工厂模式的区别？</li><li>代理模式的应用场景有哪些？</li><li>策略模式如何消除 if-else？</li></ol><h4 id="资源-12" tabindex="-1">资源 <a class="header-anchor" href="#资源-12" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://github.com/liyupi/design-pattern-guide" target="_blank" rel="noreferrer">鱼皮的设计模式教程</a> ：GitHub 免费开源</li><li>⭐ <a href="https://www.codefather.cn/course/1790979621621641217" target="_blank" rel="noreferrer">聚合搜索项目 - 鱼皮原创</a> ：运用了大量设计模式</li><li>⭐ <a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统 - 鱼皮原创</a> ：运用了多种设计模式</li><li>⭐ 《图解设计模式》：强烈推荐，用 Java 语言实现，图多、有示例代码、有习题和答案</li><li>《Head First 设计模式》：经典入门书籍</li><li>《大话设计模式》：通俗易懂</li><li>《设计模式：可复用面向对象软件的基础》：大黑书，有能力的话也可以去读</li><li><a href="https://www.bilibili.com/video/BV1G4411c7N4" target="_blank" rel="noreferrer">尚硅谷图解 Java 设计模式</a></li><li><a href="https://design-patterns.readthedocs.io/zh_CN/latest/" target="_blank" rel="noreferrer">图说设计模式</a></li></ul><h3 id="🌕-redis-14-天" tabindex="-1">🌕 Redis（14 天） <a class="header-anchor" href="#🌕-redis-14-天" aria-label="Permalink to &quot;🌕 Redis（14 天）&quot;">​</a></h3><p>⭐️ 推荐观看 <a href="https://www.bilibili.com/video/BV1a1sgzfE5d/" target="_blank" rel="noreferrer">鱼皮的 Redis 导学视频</a> ，快速了解 Redis 学习路线和关键知识。</p><p>详情请参考学习路线： <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190541746872321?type=" target="_blank" rel="noreferrer">Redis 学习路线</a></p><p>缓存是高并发系‌‌‌‌统不可或缺的技术，可以提高⁢⁢⁢⁢系统的性能和并发，而 Re⁡⁡⁡⁡dis 是实现缓存的最主流技术，因此它是后台开发必学⁠⁠⁠⁠的知识点，也是面试重点。</p><h4 id="知识-13" tabindex="-1">知识 <a class="header-anchor" href="#知识-13" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>Redis 基础</li><li>什么是缓存？</li><li>本地缓存 <ul><li>Caffeine 库</li></ul></li><li>多级缓存</li><li>Redis 分布式缓存 <ul><li>数据类型 <ul><li>常用操作</li><li>Java 操作 Redis</li><li>Spring Boot Redis Template - Redisson</li><li>主从模型搭建</li><li>哨兵集群搭建</li><li>日志持久化</li></ul></li></ul></li><li>缓存（Redis）应用场景 <ul><li>数据共享 <ul><li>单点登录</li><li>计数器</li><li>限流</li><li>点赞</li><li>实时排行榜</li><li>分布式锁</li></ul></li></ul></li><li>缓存常见问题 <ul><li>缓存雪崩 <ul><li>缓存击穿</li><li>缓存穿透</li><li>缓存更新一致性</li></ul></li></ul></li><li>相关技术：Memcached、Ehcache</li></ul><h4 id="学习建议-14" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-14" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>学会如何简单‌‌‌‌地使用缓存并不难，和数据⁢⁢⁢⁢库类似，无非就是调用 A⁡⁡⁡⁡PI 对数据进行增删改查。但是要用好 Redis⁠⁠⁠⁠，还是需要下一番功夫的。</p><p>建议的学习路径是：先能够独立使用 Redis，了解缓存的应用场景（比如缓存热点数据、实现分布式锁、计数器等）；再学习如何在 Java 中操作 Redis（推荐使用 Spring Boot + Redis 或 Redisson），并尝试把 Redis 应用到你之前做过的项目中，实际感受一下 Redis 带来的性能提升。</p><p>跟着视频教程实‌‌‌‌操一遍即可，Redis 的一⁢⁢⁢⁢些高级特性和底层原理，可以等⁡⁡⁡⁡到面试前再去深入了解。但是缓存三大问题（缓存穿透、击穿、⁠⁠⁠⁠雪崩）一定要理解，因为面试必问！</p><p>推荐大家看黑马的那‌‌‌‌套 Redis 教程，讲得非常好，⁢⁢⁢⁢结合实际项目去讲，而不是纯理论。看⁡⁡⁡⁡完之后，一定要自己动手把 Redis 加到你的项目里，哪怕只是用 R⁠⁠⁠⁠edis 缓存一下用户信息也好。</p><h4 id="经典面试题-9" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-9" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>Redis 为什么快？</li><li>Redis 有哪些常用的数据结构？</li><li>Redis RDB 和 AOF 持久化的区别，如何选择？</li><li>如何解决缓存击穿、缓存穿透、雪崩问题？</li><li>如何用 Redis 实现点赞功能，怎么设计 Key / Value？</li></ol><h4 id="资源-13" tabindex="-1">资源 <a class="header-anchor" href="#资源-13" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.codefather.cn/course/1790950013153095682" target="_blank" rel="noreferrer">伙伴匹配系统 - 鱼皮原创</a> ：项目中运用 Redis 解决实际问题</li><li>⭐ <a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">智能 BI 项目 - 鱼皮原创</a> ：运用 Redis</li><li>⭐ <a href="https://www.bilibili.com/video/BV1cr4y1671t" target="_blank" rel="noreferrer">黑马 Redis 从基础到原理实战教程</a> ：结合项目去讲，内容全面，强烈推荐</li><li><a href="https://www.bilibili.com/video/BV1Rv41177Af" target="_blank" rel="noreferrer">尚硅谷 - 2021 最新 Redis 6 入门到精通教程</a> ：基于 Redis 6，讲解详细</li><li>⭐ <a href="https://www.codefather.cn/course/1789189862986850306/section/1789190541746872321" target="_blank" rel="noreferrer">Redis 完整学习路线 - 编程导航</a></li><li>《Redis 实战》：经典书籍</li></ul><h3 id="🌖-消息队列-14-天" tabindex="-1">🌖 消息队列（14 天） <a class="header-anchor" href="#🌖-消息队列-14-天" aria-label="Permalink to &quot;🌖 消息队列（14 天）&quot;">​</a></h3><p>⭐️ 推荐观看 <a href="https://www.bilibili.com/video/BV12qmyBQEwL" target="_blank" rel="noreferrer">鱼皮的消息队列 RabbitMQ 导学视频</a> ，快速了解消息队列学习路线和关键知识。</p><p>关于消息队列的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990755245742927874" target="_blank" rel="noreferrer">消息队列学习路线（通用）</a></p><p>消息队列是用于‌‌‌‌传输和保存消息的容器，也是⁢⁢⁢⁢大型分布式系统中常用的技术⁡⁡⁡⁡，主要解决应用耦合、异步消息、流量削锋等问题。后台开⁠⁠⁠⁠发必学，也是面试重点。</p><h4 id="知识-14" tabindex="-1">知识 <a class="header-anchor" href="#知识-14" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>消息队列的作用</li><li>RabbitMQ 消息队列 <ul><li>生产消费模型 <ul><li>交换机模型</li><li>死信队列</li><li>延迟队列</li><li>消息持久化</li><li>Java 操作</li><li>集群搭建</li></ul></li></ul></li><li>相关技术：Kafka、ActiveMQ、TubeMQ、RocketMQ</li></ul><h4 id="学习建议-15" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-15" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>消息队列听起来很‌‌‌‌高大上，但其实学会如何使用并不⁢⁢⁢⁢难，无非就是调用 API 去生⁡⁡⁡⁡产、转发和消费消息。难的是理解什么时候该用消息队列，以及如何⁠⁠⁠⁠设计好消息队列的使用方案。</p><p>建议先能够独立使用消息‌‌‌‌队列，了解它的应用场景（比如异步处理、流量⁢⁢⁢⁢削峰、系统解耦）；再学习如何在 Java ⁡⁡⁡⁡中操作消息队列中间件（使用 Spring Boot 整合），并尝试把消息队列应用到你⁠⁠⁠⁠的项目中，实际感受一下它带来的好处。</p><p><strong>选择哪个消息队列呢？</strong></p><p>市面上消息队列很‌‌‌‌多（RabbitMQ、Kafk⁢⁢⁢⁢a、RocketMQ 等），初⁡⁡⁡⁡学者建议先学习 RabbitMQ，比 Kafka 要好理解一⁠⁠⁠⁠些，而且企业中用得也很多。</p><ul><li>关于 RabbitMQ 的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990755291993518082" target="_blank" rel="noreferrer">RabbitMQ 消息队列学习路线</a></li><li>关于 Kafka 的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990755332183339010" target="_blank" rel="noreferrer">Kafka 消息队列学习路线</a></li><li>关于 RocketMQ 的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990755369533616130" target="_blank" rel="noreferrer">RocketMQ 消息队列学习路线</a></li></ul><p>跟着视频教‌‌‌‌程实操一遍即⁢可⁢，⁢原⁢理和高⁡级特⁡性可⁡以等⁡到面试前再去深⁠入了解⁠。</p><p>推荐跟着鱼皮的 <a href="https://www.codefather.cn/course/1790980531403927553" target="_blank" rel="noreferrer">智能 BI 项目</a> 或者 <a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统</a> 学习，这两个项目都用到了消息队列解决实际问题（BI 项目用消息队列异步生成图表，判题系统用消息队列解耦），能让你理解消息队列在真实项目中是怎么用的。</p><h4 id="经典面试题-10" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-10" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>使用消息队列有哪些优缺点？</li><li>如何保证消息消费的幂等性？</li><li>消息队列有哪些路由模型？</li><li>你是否用过消息队列，解决过什么问题？</li></ol><p>更多消息队列面试题：</p><ul><li><a href="https://www.mianshiya.com/bank/1801255316257841153" target="_blank" rel="noreferrer">消息队列面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1850081848441466881" target="_blank" rel="noreferrer">RabbitMQ 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1850081899830079490" target="_blank" rel="noreferrer">RocketMQ 面试题 - 面试鸭</a></li></ul><h4 id="资源-14" tabindex="-1">资源 <a class="header-anchor" href="#资源-14" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">智能 BI 项目 - 鱼皮原创</a> ：项目中运用消息队列异步生成图表</li><li>⭐ <a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统 - 鱼皮原创</a> ：运用消息队列削峰</li><li>⭐ <a href="https://www.bilibili.com/video/BV1Xm4y1i7HP" target="_blank" rel="noreferrer">2024 黑马 RabbitMQ 消息队列教程</a> ：适合快速入门</li><li><a href="https://www.bilibili.com/video/BV1cb4y1o7zz" target="_blank" rel="noreferrer">尚硅谷 - 2021 最新 RabbitMQ 教程</a> ：更加全面</li><li>⭐ <a href="https://www.codefather.cn/course/1793910027205795841" target="_blank" rel="noreferrer">编程导航原创 Rocket MQ 消息队列专栏</a></li><li><a href="http://rabbitmq.mr-ping.com/" target="_blank" rel="noreferrer">RabbitMQ 中文文档</a></li><li>《RabbitMQ 实战：高效部署分布式消息队列》：经典书籍</li><li>⭐ <a href="http://tryrabbitmq.com/" target="_blank" rel="noreferrer">RabbitMQ 在线模拟器</a></li></ul><h3 id="🌖-nginx-14-天" tabindex="-1">🌖 Nginx（14 天） <a class="header-anchor" href="#🌖-nginx-14-天" aria-label="Permalink to &quot;🌖 Nginx（14 天）&quot;">​</a></h3><p>⭐️ 推荐观看 <a href="https://www.bilibili.com/video/BV1TW1LYkE59" target="_blank" rel="noreferrer">鱼皮的 Nginx 导学视频</a> ，快速了解 Nginx 学习路线和关键知识</p><p>关于 Nginx 的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1850847315113381889" target="_blank" rel="noreferrer">Nginx 学习路线</a></p><p>Nginx 是主流‌‌‌‌的、开源的、高性能的 HTTP 和⁢⁢⁢⁢反向代理 web 服务器，可以用于⁡⁡⁡⁡挂载网站、请求转发、负载均衡、网关路由等。前后端开发同学都需要学习，⁠⁠⁠⁠在后端开发的面试中有时会考到。</p><h4 id="知识-15" tabindex="-1">知识 <a class="header-anchor" href="#知识-15" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>Nginx 作用</li><li>正向代理</li><li>反向代理（负载均衡）</li><li>常用命令</li><li>配置</li><li>动静分离（网站部署）</li><li>集群搭建</li><li>相关技术：HAProxy、Apache</li></ul><h4 id="学习建议-16" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-16" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>Nginx‌‌‌‌ 是个非常实⁢用⁢的⁢工⁢具，学⁡会了⁡你就⁡能自⁡己搭建网站、做⁠负载⁠均衡了。</p><p>1）Nginx 的基本使用非常简单，甚至不需要看视频教程，跟着一篇文章或者官方文档就能够用它来部署网站、实现反向代理。鱼皮之前录过一个 <a href="https://www.bilibili.com/video/BV1rU4y1J785/" target="_blank" rel="noreferrer">手把手搭建个人网站的视频教程</a> ，10 分钟就能学会基本操作。</p><p>2）实践出真知：‌‌‌‌建议自己买台服务器，实际部署几⁢⁢⁢⁢个网站试试。比如把你之前做的项⁡⁡⁡⁡目部署到服务器上，用 Nginx 做反向代理和负载均衡。实际⁠⁠⁠⁠操作一次，胜过看十遍理论。</p><p>3）要理解 Nginx 的配‌‌‌‌置：虽然 Nginx 配置看起来很简单，但是在企业中，⁢⁢⁢⁢往往需要针对实际场景去写一些特定的配置（比如配置 HT⁡⁡⁡⁡TPS、配置缓存、配置限流等）。因此建议有时间的话，多实践 Nginx 的各种配置，了解 Nginx 的设计⁠⁠⁠⁠思想，对今后自己设计系统时也有帮助。</p><h4 id="经典面试题-11" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-11" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>Nginx 有哪些作用？</li><li>Nginx 为什么支持高并发？</li><li>Nginx 有哪些负载均衡策略？</li><li>什么是 Nginx 惊群问题，如何解决它？</li></ol><p>更多 Nginx 面试题：</p><ul><li><a href="https://www.mianshiya.com/bank/1824363422328864769" target="_blank" rel="noreferrer">Nginx 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1824363578297618433" target="_blank" rel="noreferrer">Nginx 原理面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1824363701287194625" target="_blank" rel="noreferrer">Nginx 配置面试题 - 面试鸭</a></li></ul><h4 id="资源-15" tabindex="-1">资源 <a class="header-anchor" href="#资源-15" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1zJ411w7SV" target="_blank" rel="noreferrer">尚硅谷 - Nginx 教程由浅入深</a> ：讲得比较全面</li><li>⭐ <a href="https://www.bilibili.com/video/BV1rU4y1J785/" target="_blank" rel="noreferrer">鱼皮 - 手把手从 0 搭建个人网站</a> ：简单演示 Nginx 部署网站</li><li><a href="https://www.digitalocean.com/community/tools/nginx?global.app.lang=zhCN" target="_blank" rel="noreferrer">Nginx 配置在线生成</a></li></ul><h3 id="🌗-netty-网络编程-21-天" tabindex="-1">🌗 Netty 网络编程（21 天） <a class="header-anchor" href="#🌗-netty-网络编程-21-天" aria-label="Permalink to &quot;🌗 Netty 网络编程（21 天）&quot;">​</a></h3><p>关于 Netty 网络编程的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990754668925464578" target="_blank" rel="noreferrer">Netty 网络编程学习路线</a></p><p>开源的 J‌‌‌‌ava 网络编程框⁢⁢⁢⁢架，用于开发高性能⁡⁡⁡⁡（事件驱动、异步非阻塞）、高可靠的网⁠⁠⁠⁠络服务器和客户端程序。</p><p>很多网络框架和‌‌‌‌服务器程序都用到了 Nett⁢⁢⁢⁢y 作为底层，学好 Nett⁡⁡⁡⁡y 不仅可以让我们自己实现高性能服务器，也能更好地理解其⁠⁠⁠⁠他的框架应用、阅读源码。</p><h4 id="知识-16" tabindex="-1">知识 <a class="header-anchor" href="#知识-16" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>IO 模型（BIO / NIO）</li><li>Channel</li><li>Buffer</li><li>Seletor</li><li>Netty 模型</li><li>WebSocket 编程（动手做个聊天室）</li><li>相关技术：Vertx（中文文档： <a href="http://vertxchina.github.io/vertx-translation-chinese/" target="_blank" rel="noreferrer">http://vertxchina.github.io/vertx-translation-chinese/</a> ，比 Netty 简单多了，实在看不懂 Netty 也可以学习下这个）</li></ul><h4 id="学习建议-17" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-17" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>Netty‌‌‌‌ 是个相对比⁢较⁢难⁢的⁢技术，⁡不像⁡之前⁡学的⁡ SSM 框架⁠那么容⁠易上手。</p><p>Netty 还是需‌‌‌‌要一定学习成本的，一方面是国内资源相⁢⁢⁢⁢对缺乏，另一方面很多重要的概念（比如⁡⁡⁡⁡ NIO、Reactor 模型）比较抽象，要多动手写代码调试才能理解。第⁠⁠⁠⁠一遍看不懂很正常，不要气馁。</p><p>对于大多数同学来说，建议先从视‌‌‌‌频入门，了解 Netty 的基本用法和核心概念就行，不建议在⁢⁢⁢⁢ Netty 上花太多时间。因为在实际工作中，直接用到 Ne⁡⁡⁡⁡tty 的场景并不多（除非你做的是框架开发、IM 系统之类的），面试的时候一般也就考察一些 Netty 背后的思想（比如⁠⁠⁠⁠ NIO、零拷贝）而非框架本身的语法细节。</p><p>建议做个小‌‌‌‌项目，比如可以跟着教⁢⁢⁢⁢程做一个简单的 We⁡⁡⁡⁡bSocket 聊天室，这样对 Nett⁠⁠⁠⁠y 的理解会更深刻。</p><h4 id="经典面试题-12" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-12" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>Netty 有哪些优点？</li><li>什么是 NIO？</li><li>介绍 Netty 的零拷贝机制</li></ol><h4 id="资源-16" tabindex="-1">资源 <a class="header-anchor" href="#资源-16" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1DJ411m7NR" target="_blank" rel="noreferrer">尚硅谷 Netty 教程</a> ：系统讲解 Netty</li><li>《Netty 实战》：经典书籍</li></ul><h3 id="🌖-微服务-60-天" tabindex="-1">🌖 微服务（60 天） <a class="header-anchor" href="#🌖-微服务-60-天" aria-label="Permalink to &quot;🌖 微服务（60 天）&quot;">​</a></h3><p>关于微服务的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990754562939596801" target="_blank" rel="noreferrer">Spring Cloud 微服务学习路线</a></p><p>随着互联网‌‌‌‌的发展，项目越来⁢⁢⁢越⁢复杂，单机且庞⁡⁡⁡大的⁡巨石项目已无法满足开发、运维⁠⁠⁠、并发、可靠⁠性等需求。</p><p>因此，后台架构‌‌‌‌不断演进，可以将庞大的项目⁢⁢⁢⁢拆分成一个个职责明确、功能⁡⁡⁡⁡独立的细小模块，模块可以部署在多台服务器上，相互配合⁠⁠⁠⁠协作，提供完整的系统能力。</p><p>换言之，想做大型项目，这块儿一定要好好学！</p><h4 id="知识-17" tabindex="-1">知识 <a class="header-anchor" href="#知识-17" aria-label="Permalink to &quot;知识&quot;">​</a></h4><h5 id="dubbo" tabindex="-1">Dubbo <a class="header-anchor" href="#dubbo" aria-label="Permalink to &quot;Dubbo&quot;">​</a></h5><ul><li>架构演进</li><li>RPC</li><li>Zookeeper</li><li>服务提供者</li><li>服务消费者</li><li>项目搭建</li><li>相关技术：DubboX（对 Dubbo 的扩展）</li></ul><h5 id="🌖-微服务" tabindex="-1">🌖 微服务 <a class="header-anchor" href="#🌖-微服务" aria-label="Permalink to &quot;🌖 微服务&quot;">​</a></h5><ul><li>微服务概念</li><li>Spring Cloud 框架 <ul><li>子父工程 <ul><li>服务注册和发现</li><li>注册中心 Eureka、Zookeeper、Consul</li><li>Ribbon 负载均衡</li><li>Feign 服务调用</li><li>Hystrix 服务限流、降级、熔断</li><li>Resilience4j 服务容错</li><li>Gateway（Zuul）微服务网关</li><li>Config 分布式配置中心</li><li>分布式服务总线</li><li>Sleuth + Zipkin 分布式链路追踪</li></ul></li></ul></li><li>Spring Cloud Alibaba <ul><li>Nacos 注册、配置中心 <ul><li>OpenFeign 服务调用</li><li>Sentinel 流控</li><li>Seata 分布式事务</li></ul></li></ul></li></ul><h5 id="接口管理" tabindex="-1">接口管理 <a class="header-anchor" href="#接口管理" aria-label="Permalink to &quot;接口管理&quot;">​</a></h5><ul><li>Swagger 接口文档</li><li>Postman 接口测试</li><li>相关技术：YApi、ShowDoc</li></ul><h4 id="学习建议-18" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-18" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>微服务这块‌‌‌‌内容听起来很⁢高⁢大⁢上⁢，但其⁡实学⁡起来⁡没那⁡么难，不要被那⁠些专业术语⁠吓到⁠了。</p><p>先说说学习路径：时间不急的‌‌‌‌话，建议先从 Dubbo 学起，对分布式、RPC、微⁢⁢⁢⁢服务有些基本的了解，再去食用 Spring Clou⁡⁡⁡⁡d 全家桶会更香。学完 Spring Cloud 后，再去学 Spring Cloud Alibaba ⁠⁠⁠⁠就很简单了，因为很多概念都是相通的。</p><p>对于微服务的学习，原理‌‌‌‌ + 实践都很重要，但也不要被各种高大上的⁢⁢⁢⁢词汇唬住了。什么注册中心、配置中心、服务网⁡⁡⁡⁡关，听起来很复杂，其实都是上层（应用层）的东西，基本没有什么算法，跟着视频教程学，把⁠⁠⁠⁠项目跑起来，其实还是很好理解的。</p><p><strong>记住，先会用再深入！</strong></p><p>分布式相关知识非‌‌‌‌常多，但这里不用刻意去背，先通⁢⁢⁢⁢过视频教程实战使用一些微服务框⁡⁡⁡⁡架，把项目跑起来，对各个组件有个直观的认识就可以了。等到面试⁠⁠⁠⁠前，再去深入学习原理和细节。</p><p>大厂面试的时候很少问 S‌‌‌‌pring Cloud 框架的细节（比如某个配置⁢⁢⁢⁢怎么写），更多的是微服务以及各组件的一些思想，比⁡⁡⁡⁡如为什么需要注册中心、网关有什么好处、如何保证分布式系统的一致性等。所以学的时候，要多思考 &quot;为⁠⁠⁠⁠什么需要这个组件，它解决了什么问题&quot;。</p><h4 id="经典面试题-13" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-13" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>什么是微服务，有哪些优缺点？</li><li>什么是注册中心，能解决什么问题？</li></ol><p>更多微服务面试题：</p><ul><li><a href="https://www.mianshiya.com/bank/1797453053310402561" target="_blank" rel="noreferrer">SpringCloud 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1801127500832907266" target="_blank" rel="noreferrer">Dubbo 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1804410872994144257" target="_blank" rel="noreferrer">Zookeeper 面试题 - 面试鸭</a></li></ul><h4 id="资源-17" tabindex="-1">资源 <a class="header-anchor" href="#资源-17" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.codefather.cn/course/1790979723916521474" target="_blank" rel="noreferrer">API 开放平台 - 鱼皮原创</a> ：运用 Dubbo 微服务和 Gateway 网关</li><li>⭐ <a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统 - 鱼皮原创</a> ：单体项目改造为微服务架构</li><li>⭐ <a href="https://www.bilibili.com/video/BV1UJc2ezEFU" target="_blank" rel="noreferrer">2025 尚硅谷 SpringCloud 最新教程</a> ：2025 最新版，从入门到大牛，内容全面</li><li>⭐ <a href="https://www.bilibili.com/video/BV1kH4y1S7wz" target="_blank" rel="noreferrer">黑马 Spring Cloud 视频教程</a> ：11 小时，非常凝练，适合快速入门</li><li>⭐ <a href="https://www.bilibili.com/video/BV1ns411c7jV" target="_blank" rel="noreferrer">尚硅谷 Dubbo 教程</a> ：RPC 框架入门必看</li><li><a href="https://www.bilibili.com/video/BV18E411x7eT" target="_blank" rel="noreferrer">尚硅谷 SpringCloud（H版&amp;alibaba）框架开发教程</a> ：对比讲解，内容更全面</li><li><a href="https://dubbo.apache.org/zh/" target="_blank" rel="noreferrer">Apache Dubbo 官方文档</a></li><li><a href="https://github.com/alibaba/spring-cloud-alibaba/blob/master/README-zh.md" target="_blank" rel="noreferrer">Spring Cloud Alibaba 官方文档</a></li><li><a href="https://doc.xiaominfo.com/" target="_blank" rel="noreferrer">Swagger 教学文档</a> ：跟着快速开始直接用就好了</li></ul><h3 id="🌖-容器-7-天" tabindex="-1">🌖 容器（7 天） <a class="header-anchor" href="#🌖-容器-7-天" aria-label="Permalink to &quot;🌖 容器（7 天）&quot;">​</a></h3><p>使用容器技术的好处可太多了！</p><p><strong>将应用和环境进行封装，相互隔离、独立部署。</strong> 不仅能够提高安全性、提高开发和维护效率，还能便于实现微服务、持续集成和交付。</p><p>关于 Docker 容器化的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990754953097949186" target="_blank" rel="noreferrer">Docker 容器化学习路线</a> ；关于 Kubernetes 容器编排的详细学习，可以查看 <a href="https://www.codefather.cn/course/1789189862986850306/section/1990754993086443521" target="_blank" rel="noreferrer">Kubernetes 学习路线</a> 。</p><h4 id="知识-18" tabindex="-1">知识 <a class="header-anchor" href="#知识-18" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>🌖 Docker <ul><li>容器概念 <ul><li>镜像</li><li>部署服务</li><li>Dockerfile</li><li>Docker Compose</li><li>Docker Machine</li><li>Docker Swarm</li><li>多阶段构建</li></ul></li></ul></li><li>🌘 K8S（Kubernetes） <ul><li>K8S 架构 <ul><li>工作负载</li><li>资源类型 - Pod - Pod 生命周期 - Pod 安全策略</li><li>K8S 组件</li><li>K8S 对象</li><li>部署应用</li><li>服务</li><li>Ingress</li><li>Kubectl 命令行</li><li>集群管理</li></ul></li></ul></li><li>相关技术：Apache Mesos、Mesosphere</li></ul><h4 id="学习建议-19" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-19" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>容器技术（‌‌‌‌Docker）⁢⁢是⁢现⁢在后端开发⁡⁡的标⁡配，⁡一定要学！但是 K8⁠⁠S 可⁠以先不急。</p><p>Docker 真的很实用，能‌‌‌‌让你的项目部署变得非常简单。不用再担心 &quot;在我电脑上能⁢⁢⁢⁢跑，在服务器上跑不起来&quot; 的问题了。建议跟着视频教程，⁡⁡⁡⁡把 Docker 的基本操作（拉取镜像、运行容器、编写 Dockerfile）都实践一遍。然后试着用 Doc⁠⁠⁠⁠ker 部署你的项目，感受一下容器化的好处。</p><p>K8S（Kuberne‌‌‌‌tes）是容器编排平台，学习成本比较高。对⁢⁢⁢⁢于刚入门的同学来说，可以先不学，等工作后有⁡⁡⁡⁡需要再学也不迟。实际工作中，企业一般都有现成的 K8S 平台或者运维团队负责，开发同⁠⁠⁠⁠学只需要会用 Docker 就够了。</p><p>容器技术面‌‌‌‌试考察得不多，主⁢⁢⁢要⁢是考察你是否会⁡⁡⁡用 ⁡Docker。所以不用花太多⁠⁠⁠时间，会基本⁠操作就行。</p><h4 id="经典面试题-14" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-14" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>什么是容器？</li><li>使用 Docker 有哪些好处？</li><li>如何快速启动多个 Docker 节点？</li></ol><p>更多容器面‌‌‌‌试题：   ⁢ ⁢ ⁢ ⁢   ⁡  ⁡  ⁡  ⁡       ⁠   ⁠    ⁠</p><ul><li><a href="https://www.mianshiya.com/bank/1812067352871829505" target="_blank" rel="noreferrer">Docker 面试题 - 面试鸭</a></li><li><a href="https://www.mianshiya.com/bank/1812067408974839809" target="_blank" rel="noreferrer">Kubernetes 面试题 - 面试鸭</a></li></ul><h4 id="资源-18" tabindex="-1">资源 <a class="header-anchor" href="#资源-18" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统 - 鱼皮原创</a> ：项目中运用 Docker 实现代码沙箱</li><li>⭐ <a href="https://www.bilibili.com/video/BV1og4y1q7M4" target="_blank" rel="noreferrer">狂神说 - Docker 最新超详细版教程</a> ：通俗易懂</li><li><a href="https://www.bilibili.com/video/BV1K5411N7j8" target="_blank" rel="noreferrer">K8S 视频教程</a></li><li><a href="https://www.zhihu.com/pub/reader/119632192" target="_blank" rel="noreferrer">《深入浅出 Docker》</a></li><li><a href="https://vuepress.mirror.docker-practice.com/" target="_blank" rel="noreferrer">Docker — 从入门到实践</a></li><li><a href="https://docs.docker.com/get-started/" target="_blank" rel="noreferrer">Docker 官方文档</a></li><li><a href="https://www.docker.org.cn/" target="_blank" rel="noreferrer">Docker 中文社区</a> ：有很多 Docker 技术文章和学习笔记</li><li><a href="https://hub.docker.com/" target="_blank" rel="noreferrer">Docker Hub</a> ：Docker 镜像仓库</li></ul><h3 id="🌗-ci-cd-3-天" tabindex="-1">🌗 CI / CD（3 天） <a class="header-anchor" href="#🌗-ci-cd-3-天" aria-label="Permalink to &quot;🌗 CI / CD（3 天）&quot;">​</a></h3><p>CI / CD 是指 <strong>持续集成 / 持续交付</strong> ，贯穿整个研发到项目上线的过程，提高效率。</p><p><img src="https://pic.code-nav.cn/migrate_image/f67071b07aba00ea1667e71eff620acd.webp" alt=""></p><p>大公司一般都有自己的 CI / CD 平台。</p><h4 id="知识-19" tabindex="-1">知识 <a class="header-anchor" href="#知识-19" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>什么是 CI / CD</li><li>CI / CD 有什么好处</li><li>使用任一 CI / CD 平台</li><li>相关技术：Jenkins、GitLab、微信云托管</li></ul><h4 id="学习建议-20" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-20" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>了解它是什么‌‌‌‌，并且实战使用任一 C⁢⁢⁢⁢I / CD 平台，感⁡⁡⁡⁡受它和传统开发运维到底有什么不同，就足够了。⁠⁠⁠⁠其实很简单，不要花太多时间。</p><p>真正要自己去搭建的时候，跟着官方文档来就行。</p><h4 id="资源-19" tabindex="-1">资源 <a class="header-anchor" href="#资源-19" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li><a href="https://www.bilibili.com/video/BV1GW411w7pn" target="_blank" rel="noreferrer">尚硅谷 - Jenkins 持续集成工具教程</a> ：实在要用到 Jenkins 再去学</li><li><a href="https://www.jenkins.io/zh/" target="_blank" rel="noreferrer">Jenkins 官方文档</a> ：有很多案例，要用的时候查一下就行</li><li>⭐ <a href="https://cloud.weixin.qq.com/cloudrun" target="_blank" rel="noreferrer">微信云托管</a></li><li><a href="https://cloud.tencent.com/product/webify" target="_blank" rel="noreferrer">前端托管 Webify</a> ：鱼皮有 <a href="https://www.bilibili.com/video/BV11V411p7vf/" target="_blank" rel="noreferrer">视频教程</a></li></ul><h3 id="练手项目-2" tabindex="-1">练手项目 <a class="header-anchor" href="#练手项目-2" aria-label="Permalink to &quot;练手项目&quot;">​</a></h3><p>学习完框架‌‌‌‌后，即可跟着鱼皮的原⁢⁢⁢⁢创项目教程系列边学边做⁡⁡⁡⁡项目。用项目驱动学习，更快地掌握后端必⁠⁠⁠⁠学技术，并直接写在简历上：</p><ul><li>⭐ <a href="https://www.codefather.cn/post/1797431216467001345" target="_blank" rel="noreferrer">项目实战 - 鱼皮原创项目教程系列</a> （保姆级全栈项目，带简历写法和面试题）</li></ul><p>其他开源项目：</p><ul><li><a href="https://github.com/qiurunze123/miaosha" target="_blank" rel="noreferrer">miaosha</a> （秒杀系统设计和实现）</li><li><a href="https://github.com/macrozheng/mall" target="_blank" rel="noreferrer">Mall</a> （包括前台商城系统及后台管理系统，基于 SpringBoot+MyBatis 实现）</li><li><a href="https://github.com/paascloud/paascloud-master" target="_blank" rel="noreferrer">paascloud-master</a> （基于 Spring Cloud + Vue + oAuth2.0 前后端分离商城系统）</li><li><a href="https://github.com/macrozheng/mall-swarm" target="_blank" rel="noreferrer">mall-swarm</a> （微服务商城系统）</li><li><a href="https://github.com/hfbin/Seckill" target="_blank" rel="noreferrer">SecKill</a> （基于 SpringBoot+Mybatis+Redis+RabbitMQ 秒杀系统）</li><li><a href="https://github.com/zhangdaiscott/jeecg-boot" target="_blank" rel="noreferrer">jeecg-boot</a> （低代码开发平台）</li><li><a href="https://github.com/Jackson0714/PassJava-Platform" target="_blank" rel="noreferrer">PassJava-Platform</a> （面试刷题的 Spring Cloud 开源系统）</li></ul><h3 id="尾声-3" tabindex="-1">尾声 <a class="header-anchor" href="#尾声-3" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>看到这里，相信你已经感叹：编程语言一辈子学不完了！</p><p>但是，不用担心，‌‌‌通过‌对这么多知识点的学习，相信⁢⁢⁢你已经有了一定的积⁢累，也不知不⁡⁡⁡觉地锻炼了自主学习能力、资源检⁡索能力、代码阅读能力、问题解决⁠⁠⁠能力，之后的学习会越来越轻松。               ⁠</p><p>接下来，可‌‌‌‌以试着用你学到的⁢⁢⁢技⁢术来解决实际的⁡⁡⁡问题⁡，自主从 0 开始做一些项目⁠⁠⁠，保持⁠编程手感。</p><h2 id="阶段-5-项目实战" tabindex="-1">阶段 5：项目实战 <a class="header-anchor" href="#阶段-5-项目实战" aria-label="Permalink to &quot;阶段 5：项目实战&quot;">​</a></h2><h3 id="目标-4" tabindex="-1">目标 <a class="header-anchor" href="#目标-4" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>综合所学技‌‌‌‌术从 0 到 ⁢⁢1⁢ ⁢开发和上线⁡⁡一个⁡全面⁡、有特色的、可以写进⁠⁠简历的⁠个人项目。</p><h3 id="学习建议-21" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-21" aria-label="Permalink to &quot;学习建议&quot;">​</a></h3><p>这个阶段是‌‌‌‌最关键的，能⁢不⁢能⁢找⁢到工作⁡，很⁡大程⁡度上⁡取决于你的项目⁠经历。</p><p><strong>为什么要做项目？</strong></p><p>其实在之前的框架学习‌‌‌‌视频中应该就做过几个项目了，但相对不够完⁢⁢⁢⁢整和体系化。要想在简历上写得出彩，一定要⁡⁡⁡⁡有 1-2 个拿得出手的完整项目，最好是从需求分析、数据库设计、接口开发、前端页⁠⁠⁠⁠面到部署上线的完整流程都经历过。</p><p><strong>如何选择项目？</strong></p><p>1）有想法的‌‌‌‌同学：可以做任何自己想做⁢⁢⁢⁢的项目，推荐参加一些作品⁡⁡⁡⁡类竞赛（比如中国软件杯、互联网+），练手、拿奖、⁠⁠⁠⁠收获项目经历一举三得。</p><p>2）暂时没想法的同学：强烈建议先跟着 <a href="https://www.codefather.cn/post/1797431216467001345" target="_blank" rel="noreferrer">鱼皮的原创项目教程系列</a> 做，从 0 到 1 保姆级带你做完整项目，还会教你怎么写简历、怎么应对面试。做完 2-3 个项目后，你就知道怎么独立做项目了。</p><p>3）有一定基础的同学：可以试着用 GitHub 上的优质开源项目源码来学习，但是要注意选择 <strong>较新的</strong> 、 <strong>有配套文档的</strong> 、 <strong>star 数较高的</strong> 项目。</p><p><strong>一般要做几个项目？</strong></p><p>建议至少完整做 2 个‌‌‌‌项目，一个简单的（比如管理系统），一个稍微⁢⁢⁢⁢复杂的（比如包含微服务、缓存、消息队列等技⁡⁡⁡⁡术的项目）。不要贪多，2 个精品项目胜过 10 个半成品              ⁠⁠⁠⁠</p><p><strong>注意，必须要从 0 到 1 自己手写！</strong></p><p>不要只是下载源‌‌‌‌码跑一跑就完事了，那样面试⁢⁢⁢⁢的时候会露馅。做项目的时候⁡⁡⁡⁡，建议边做边记录，把遇到的问题和解决方案都记下来，面⁠⁠⁠⁠试的时候能派上大用场。</p><p>下面推荐一‌些优质的项目实战视频⁢教程和开源项目源码。⁡                    ⁠</p><h3 id="视频教程" tabindex="-1">视频教程 <a class="header-anchor" href="#视频教程" aria-label="Permalink to &quot;视频教程&quot;">​</a></h3><p>强烈推荐 <a href="https://www.codefather.cn/post/1797431216467001345" target="_blank" rel="noreferrer">鱼皮原创项目教程系列</a> ， <a href="https://www.codefather.cn/" target="_blank" rel="noreferrer">编程导航</a> 鱼友可学。</p><p><strong>阶段 1 - 新手入门</strong> （适合刚学完框架的同学）：</p><ol><li><a href="https://www.codefather.cn/course/1790943469757837313" target="_blank" rel="noreferrer">用户中心项目</a> ：保姆级前后端完整项目教程，系统学习项目开发流程和上线方法</li><li><a href="https://www.codefather.cn/course/1790950013153095682" target="_blank" rel="noreferrer">伙伴匹配系统</a> ：移动端网站，学习 Redis、事务、并发编程等后端知识</li><li><a href="https://www.codefather.cn/course/1943267371799080961" target="_blank" rel="noreferrer">AI 编程助手</a> ：适合新手入门 AI 应用开发，实战 LangChain4j 框架</li></ol><p><strong>阶段 2 - 真实业务实战</strong> （业务完整，极具实用价值）：</p><ol start="4"><li><a href="https://www.codefather.cn/course/1948291549923344386" target="_blank" rel="noreferrer">AI 零代码应用生成平台</a> ：对标大厂，实战 AI 智能体、微服务架构、多种设计模式</li><li><a href="https://www.codefather.cn/course/1864210260732116994" target="_blank" rel="noreferrer">智能协同云图库</a> ：实战文件存管、权限控制、实时协同等企业级场景</li><li><a href="https://www.codefather.cn/course/1790274408835506178" target="_blank" rel="noreferrer">AI 答题应用平台</a> ：深入业务场景，学习分库分表、分布式锁、RxJava 响应式编程</li><li><a href="https://www.codefather.cn/course/1826803928691945473" target="_blank" rel="noreferrer">智能面试刷题平台</a> ：实战 Redis 多级缓存、Elasticsearch、Sentinel 流控</li><li><a href="https://www.codefather.cn/course/1790980795074654209" target="_blank" rel="noreferrer">代码生成器共享平台</a> ：学习命令行开发、模板引擎、Vert.x、设计模式</li></ol><p><strong>阶段 3 - 快速补充技术栈</strong> （小而精，侧重某一项技术）：</p><ol start="9"><li><a href="https://www.codefather.cn/course/1915010091721236482" target="_blank" rel="noreferrer">AI 超级智能体项目</a> ：学习 AI 应用开发，掌握新时代程序员必知的 AI 技术</li><li><a href="https://www.codefather.cn/course/1790979621621641217" target="_blank" rel="noreferrer">聚合搜索平台</a> ：学习爬虫 + Elastic Stack + 设计模式</li><li><a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">智能 BI 项目</a> ：学习线程池 + RabbitMQ 消息队列 + AI 应用开发</li></ol><p><strong>阶段 4 - 技术进阶</strong> （涉及架构设计，更侧重技术提升）：</p><ol start="12"><li><a href="https://www.codefather.cn/course/1790979723916521474" target="_blank" rel="noreferrer">API 开放平台</a> ：大厂业务，学习 SDK 开发 + API 签名认证 + Dubbo + Gateway 网关</li><li><a href="https://www.codefather.cn/course/1790980707917017089" target="_blank" rel="noreferrer">OJ 判题系统</a> ：学习多种设计模式 + 微服务改造 + Docker 代码沙箱</li><li><a href="https://www.codefather.cn/course/1768543954720022530" target="_blank" rel="noreferrer">手写 RPC 框架</a> ：从 0 到 1 开发轮子，大幅提升架构设计能力</li></ol><p>更多项目详情和学习建议： <a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">鱼皮项目学习建议（必读）</a></p><p>公开视频教程：</p><ul><li><a href="https://www.bilibili.com/video/BV1dQ4y1A75e" target="_blank" rel="noreferrer">尚硅谷 - 谷粒学院 - 微服务 + 全栈 - 在线教育实战项目</a> ：全栈项目，前后端讲得都很全面</li><li><a href="https://www.bilibili.com/video/BV1bE411T7oZ" target="_blank" rel="noreferrer">尚硅谷 - 尚筹网 - SSM 框架 + 微服务架构</a> ：500 多集，包含完整的用户权限管理</li><li><a href="https://www.bilibili.com/video/BV13f4y1r7fS" target="_blank" rel="noreferrer">黑马 - 24 小时搞定 Java 毕设电商项目</a></li><li><a href="https://www.bilibili.com/video/BV1Bo4y117zV" target="_blank" rel="noreferrer">黑马 Java 项目《传智健康》</a> ：超完整的企业级医疗行业项目</li><li><a href="https://www.bilibili.com/video/BV1Ub4y1f7rk" target="_blank" rel="noreferrer">黑马 Java 项目《万信金融》</a> ：企业级开发实战</li><li><a href="https://www.bilibili.com/video/BV18A411L7UX" target="_blank" rel="noreferrer">黑马 Java 项目《iHRM 人力资源管理系统》</a> ：SaaS 移动办公</li><li><a href="https://www.bilibili.com/video/BV1sZ4y1F7PD" target="_blank" rel="noreferrer">黑马 Java 项目《好客租房》</a></li></ul><h3 id="常用类库" tabindex="-1">常用类库 <a class="header-anchor" href="#常用类库" aria-label="Permalink to &quot;常用类库&quot;">​</a></h3><h4 id="工具类" tabindex="-1">工具类 <a class="header-anchor" href="#工具类" aria-label="Permalink to &quot;工具类&quot;">​</a></h4><ul><li><a href="https://github.com/google/guava" target="_blank" rel="noreferrer">Guava</a> ：谷歌开发的 Java 工具库</li><li><a href="https://github.com/apache/commons-lang" target="_blank" rel="noreferrer">Apache Commons</a> ：各类工具库，比如 commons-lang、commons-io、commons-collections 等</li><li><a href="https://github.com/looly/hutool" target="_blank" rel="noreferrer">Hutool</a> ：Java 工具集库</li><li><a href="https://github.com/projectlombok/lombok" target="_blank" rel="noreferrer">Lombok</a> ：Java 增强库，自动生成 getter/setter</li><li><a href="https://github.com/apache/httpcomponents-client" target="_blank" rel="noreferrer">Apache HttpComponents Client</a> ：HTTP 客户端库</li><li><a href="https://github.com/square/okhttp" target="_blank" rel="noreferrer">OkHttp</a> ：适用于 JVM、Android 等平台的 Http 客户端</li><li><a href="https://github.com/google/gson" target="_blank" rel="noreferrer">Gson</a> ：谷歌的 JSON 处理库</li><li><a href="https://github.com/cbeust/jcommander" target="_blank" rel="noreferrer">Jcommander</a> ：Java 命令行参数解析框架</li><li><a href="https://github.com/apache/pdfbox" target="_blank" rel="noreferrer">Apache PDFBox</a> ：PDF 操作库</li><li><a href="https://github.com/alibaba/easyexcel" target="_blank" rel="noreferrer">EasyExcel</a> ：阿里的 Excel 处理库</li><li><a href="https://github.com/apache/poi" target="_blank" rel="noreferrer">Apache POI</a> ：表格文件处理库</li></ul><h4 id="测试类" tabindex="-1">测试类 <a class="header-anchor" href="#测试类" aria-label="Permalink to &quot;测试类&quot;">​</a></h4><ul><li><a href="https://github.com/junit-team/junit4" target="_blank" rel="noreferrer">JUnit</a> ：Java 测试框架</li><li><a href="https://github.com/mockito/mockito" target="_blank" rel="noreferrer">Mockito</a> ：Java 单元测试 Mock 框架</li><li><a href="https://github.com/SeleniumHQ/selenium" target="_blank" rel="noreferrer">Selenium</a> ：浏览器自动化框架</li><li><a href="https://github.com/HtmlUnit/htmlunit" target="_blank" rel="noreferrer">htmlunit</a> ：Java 模拟浏览器</li><li><a href="https://github.com/cbeust/testng" target="_blank" rel="noreferrer">TestNG</a> ：Java 测试框架</li><li><a href="https://github.com/jacoco/jacoco" target="_blank" rel="noreferrer">Jacoco</a> ：Java 代码覆盖度库</li></ul><h4 id="其他实用库" tabindex="-1">其他实用库 <a class="header-anchor" href="#其他实用库" aria-label="Permalink to &quot;其他实用库&quot;">​</a></h4><ul><li><a href="https://github.com/cglib/cglib" target="_blank" rel="noreferrer">cglib</a> ：字节码生成库</li><li><a href="https://github.com/alibaba/arthas" target="_blank" rel="noreferrer">Arthas</a> ：Java 诊断工具</li><li><a href="https://github.com/lightbend/config" target="_blank" rel="noreferrer">config</a> ：针对 JVM 的配置库</li><li><a href="https://github.com/puniverse/quasar" target="_blank" rel="noreferrer">Quasar</a> ：Java 纤程库</li><li><a href="https://github.com/kiegroup/drools" target="_blank" rel="noreferrer">drools</a> ：Java 规则引擎</li><li><a href="https://github.com/ben-manes/caffeine" target="_blank" rel="noreferrer">Caffeine</a> ：Java 高性能缓存库</li><li><a href="https://github.com/LMAX-Exchange/disruptor" target="_blank" rel="noreferrer">Disruptor</a> ：高性能线程间消息传递库</li><li><a href="https://doc.xiaominfo.com/" target="_blank" rel="noreferrer">Knife4j</a> ：Swagger 文档增强</li><li><a href="https://github.com/coobird/thumbnailator" target="_blank" rel="noreferrer">Thumbnailator</a> ：Java 缩略图生成库</li><li><a href="https://github.com/qos-ch/logback" target="_blank" rel="noreferrer">Logback</a> ：Java 日志库</li><li><a href="https://github.com/apache/camel" target="_blank" rel="noreferrer">Apache Camel</a> ：消息传输集成框架</li><li><a href="https://github.com/quartz-scheduler/quartz" target="_blank" rel="noreferrer">Quartz</a> ：定时任务调度库</li><li><a href="https://github.com/apache/mahout" target="_blank" rel="noreferrer">Apache Mahout</a> ：机器学习库</li><li><a href="https://github.com/apache/opennlp" target="_blank" rel="noreferrer">Apache OpenNLP</a> ：NLP 工具库</li><li><a href="https://github.com/ReactiveX/RxJava" target="_blank" rel="noreferrer">RxJava</a> ：JVM 反应式编程框架</li><li><a href="https://www.ej-technologies.com/products/jprofiler/overview.html" target="_blank" rel="noreferrer">JProfiler</a> ：性能分析库</li><li><a href="https://jsoup.org/" target="_blank" rel="noreferrer">jsoup</a> ：HTML 文档解析库</li><li><a href="https://github.com/code4craft/webmagic/" target="_blank" rel="noreferrer">webmagic</a> ：Java 爬虫框架</li></ul><h3 id="idea-插件" tabindex="-1">IDEA 插件 <a class="header-anchor" href="#idea-插件" aria-label="Permalink to &quot;IDEA 插件&quot;">​</a></h3><p>工欲善其事‌‌‌‌，必先利其⁢⁢器。I⁢D⁢EA 拥有⁡⁡丰富⁡的插⁡件生态，合理使用插件⁠⁠能够显著⁠提升⁠开发效率。</p><p>这里精选一些必装的插件，更多 IDEA 插件推荐请查看：</p><ul><li>⭐ 完整的 IDEA 插件推荐文档： <a href="https://www.codefather.cn/course/1803988290715377665/section/1996102144293355522" target="_blank" rel="noreferrer">IDEA 插件精选推荐</a></li><li>⭐ 鱼皮的 IDEA 插件推荐视频： <a href="https://www.bilibili.com/video/BV1yb4y1a7Aq" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yb4y1a7Aq</a></li></ul><h4 id="精选必装插件" tabindex="-1">精选必装插件 <a class="header-anchor" href="#精选必装插件" aria-label="Permalink to &quot;精选必装插件&quot;">​</a></h4><h4 id="必装插件" tabindex="-1">必装插件 <a class="header-anchor" href="#必装插件" aria-label="Permalink to &quot;必装插件&quot;">​</a></h4><ul><li><a href="https://plugins.jetbrains.com/plugin/13710-chinese-simplified-language-pack----" target="_blank" rel="noreferrer">Chinese Language Pack</a> - 中文语言包</li><li><a href="https://plugins.jetbrains.com/plugin/8579-translation/" target="_blank" rel="noreferrer">Translation</a> - 翻译插件，鼠标选中文本右键翻译</li><li><a href="https://plugins.jetbrains.com/plugin/9792-key-promoter-x/" target="_blank" rel="noreferrer">Key Promoter X</a> - 快捷键提示插件，帮你养成使用快捷键的习惯</li><li><a href="https://plugins.jetbrains.com/plugin/10080-rainbow-brackets/" target="_blank" rel="noreferrer">Rainbow Brackets</a> - 彩虹括号，通过颜色区分括号层级</li><li><a href="https://plugins.jetbrains.com/plugin/7275-codeglance/" target="_blank" rel="noreferrer">CodeGlance</a> - 代码小地图，方便快速定位</li></ul><h4 id="效率提升插件" tabindex="-1">效率提升插件 <a class="header-anchor" href="#效率提升插件" aria-label="Permalink to &quot;效率提升插件&quot;">​</a></h4><ul><li><a href="https://plugins.jetbrains.com/plugin/2162-string-manipulation" target="_blank" rel="noreferrer">String Manipulation</a> - 字符串快捷处理</li><li><a href="https://plugins.jetbrains.com/plugin/14949-gsonformatplus" target="_blank" rel="noreferrer">GsonFormatPlus</a> - 根据 JSON 生成对象</li><li><a href="https://plugins.jetbrains.com/plugin/10119-mybatisx" target="_blank" rel="noreferrer">MyBatisX</a> - MyBatis 增强插件，自动生成代码</li><li><a href="https://plugins.jetbrains.com/plugin/12798-tabnine-ai-code-completion-js-java-python-ts-rust-go-php--more" target="_blank" rel="noreferrer">Tabnine AI Code Completion</a> - AI 代码补全</li><li><a href="https://plugins.jetbrains.com/plugin/3064-junitgenerator-v2-0" target="_blank" rel="noreferrer">JUnitGenerator V2.0</a> - 自动生成单元测试</li><li><a href="https://plugins.jetbrains.com/plugin/14280-restfultool" target="_blank" rel="noreferrer">RestfulTool</a> - 辅助 Web 开发的工具集</li><li><a href="https://plugins.jetbrains.com/plugin/8286-sequencediagram" target="_blank" rel="noreferrer">SequenceDiagram</a> - 自动生成方法调用时序图</li></ul><h4 id="代码质量插件" tabindex="-1">代码质量插件 <a class="header-anchor" href="#代码质量插件" aria-label="Permalink to &quot;代码质量插件&quot;">​</a></h4><ul><li><a href="https://plugins.jetbrains.com/plugin/1065-checkstyle-idea" target="_blank" rel="noreferrer">CheckStyle-IDEA</a> - 自动检查 Java 代码规范</li><li><a href="https://plugins.jetbrains.com/plugin/10046-alibaba-java-coding-guidelines" target="_blank" rel="noreferrer">Alibaba Java Coding Guidelines</a> - 阿里巴巴代码规范检查插件</li><li><a href="https://plugins.jetbrains.com/plugin/7973-sonarlint" target="_blank" rel="noreferrer">SonarLint</a> - 发现和修复代码的错误和漏洞</li></ul><h3 id="常用软件" tabindex="-1">常用软件 <a class="header-anchor" href="#常用软件" aria-label="Permalink to &quot;常用软件&quot;">​</a></h3><h4 id="开发相关" tabindex="-1">开发相关 <a class="header-anchor" href="#开发相关" aria-label="Permalink to &quot;开发相关&quot;">​</a></h4><ul><li><a href="https://www.jetbrains.com/idea/" target="_blank" rel="noreferrer">JetBrains IDEA</a> ：Java 集成开发环境，凭学生邮箱可申请免费使用</li><li><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a> ：插件化代码编辑器，轻量且功能强大</li><li><a href="https://www.sublimetext.com/" target="_blank" rel="noreferrer">Sublime Text</a> ：轻量代码编辑器</li><li><a href="https://www.navicat.com.cn/" target="_blank" rel="noreferrer">Navicat</a> ：数据库管理软件，支持多种数据库</li><li><a href="https://jmeter.apache.org/" target="_blank" rel="noreferrer">JMeter</a> ：Java 性能测试工具</li><li><a href="https://visualvm.github.io/" target="_blank" rel="noreferrer">JVisual VM</a> ：Java 运行状态可视化工具</li><li><a href="https://www.netsarang.com/zh/xshell/" target="_blank" rel="noreferrer">XShell</a> ：SSH 连接软件</li><li><a href="https://www.netsarang.com/zh/xftp/" target="_blank" rel="noreferrer">XFtp</a> ：FTP 连接软件</li><li><a href="https://github.com/uglide/RedisDesktopManager" target="_blank" rel="noreferrer">Redis Desktop Manager</a> ：Redis 可视化管理工具</li><li><a href="https://www.postman.com/" target="_blank" rel="noreferrer">Postman</a> ：接口测试工具</li><li><a href="https://www.vmware.com/" target="_blank" rel="noreferrer">VMware</a> ：虚拟机软件</li><li><a href="https://chocolatey.org/" target="_blank" rel="noreferrer">Chocolatey</a> ：Windows 软件包管理器</li><li><a href="https://typora.io/" target="_blank" rel="noreferrer">Typora</a> ：Markdown 写作软件</li></ul><h4 id="效率工具" tabindex="-1">效率工具 <a class="header-anchor" href="#效率工具" aria-label="Permalink to &quot;效率工具&quot;">​</a></h4><ul><li><a href="https://jianqiezhushou.com/" target="_blank" rel="noreferrer">剪切助手</a> ：强大的剪切板管理工具</li><li><a href="https://u.tools/" target="_blank" rel="noreferrer">uTools</a> ：插件化的效率工具</li><li><a href="https://www.xmind.cn/" target="_blank" rel="noreferrer">XMind</a> ：思维导图软件</li><li><a href="https://q-dir.en.softonic.com/" target="_blank" rel="noreferrer">Qdir</a> ：Windows 多窗口文件管理器</li></ul><h3 id="项目源码-50-套" tabindex="-1">项目源码（50 套） <a class="header-anchor" href="#项目源码-50-套" aria-label="Permalink to &quot;项目源码（50 套）&quot;">​</a></h3><h4 id="鱼皮原创项目" tabindex="-1">鱼皮原创项目 <a class="header-anchor" href="#鱼皮原创项目" aria-label="Permalink to &quot;鱼皮原创项目&quot;">​</a></h4><ul><li>⭐ <a href="https://www.codefather.cn/post/1797431216467001345" target="_blank" rel="noreferrer">项目实战 - 鱼皮原创项目教程系列</a> （强烈推荐）</li><li><a href="https://github.com/liyupi/sql-father-frontend-public" target="_blank" rel="noreferrer">SQL 数据生成器</a> （React + Java）</li><li><a href="https://github.com/liyupi/sql-generator" target="_blank" rel="noreferrer">结构化 SQL 语句生成器</a></li><li><a href="https://github.com/liyupi/yu-auto-reply" target="_blank" rel="noreferrer">AI 自动回复工具</a> （Java 项目）</li><li><a href="https://github.com/liyupi/father" target="_blank" rel="noreferrer">表情包网站</a> （Vue + Java）</li></ul><h4 id="电商秒杀" tabindex="-1">电商秒杀 <a class="header-anchor" href="#电商秒杀" aria-label="Permalink to &quot;电商秒杀&quot;">​</a></h4><ul><li>天猫整站 J2EE： <a href="https://how2j.cn/module/115.htm" target="_blank" rel="noreferrer">https://how2j.cn/module/115.htm</a></li><li>天猫整站 SSM： <a href="https://how2j.cn/module/134.html" target="_blank" rel="noreferrer">https://how2j.cn/module/134.html</a></li><li>天猫整站 Springboot： <a href="https://how2j.cn/module/156.html" target="_blank" rel="noreferrer">https://how2j.cn/module/156.html</a></li><li>SpringBoot 电商商城系统 Mall4j： <a href="https://github.com/gz-yami/mall4j" target="_blank" rel="noreferrer">https://github.com/gz-yami/mall4j</a></li><li>SpringBoot 完整电商系统 Mall： <a href="https://github.com/macrozheng/mall" target="_blank" rel="noreferrer">https://github.com/macrozheng/mall</a> （包括前台商城系统及后台管理系统，基于 SpringBoot+MyBatis 实现）</li><li>newbee-mall： <a href="https://github.com/newbee-ltd/newbee-mall" target="_blank" rel="noreferrer">https://github.com/newbee-ltd/newbee-mall</a> （一套电商系统，包括 newbee-mall 商城系统及 newbee-mall-admin 商城后台管理系统，基于 Spring Boot 2.X 及相关技术栈开发）</li><li>paascloud-master： <a href="https://github.com/paascloud/paascloud-master" target="_blank" rel="noreferrer">https://github.com/paascloud/paascloud-master</a> （基于 spring cloud + vue + oAuth2.0，前后端分离商城系统）</li><li>mall-swarm： <a href="https://github.com/macrozheng/mall-swarm" target="_blank" rel="noreferrer">https://github.com/macrozheng/mall-swarm</a> （一套微服务商城系统，采用了 Spring Cloud Greenwich、Spring Boot 2、MyBatis、Docker、Elasticsearch 等核心技术，同时提供了基于 Vue 的管理后台方便快速搭建系统）</li><li>onemall： <a href="https://github.com/YunaiV/onemall" target="_blank" rel="noreferrer">https://github.com/YunaiV/onemall</a> （mall 商城，基于微服务的思想，构建在 B2C 电商场景下的项目实战。核心技术栈，是 Spring Boot + Dubbo 。未来，会重构成 Spring Cloud Alibaba）</li><li>litemall： <a href="https://github.com/linlinjava/litemall" target="_blank" rel="noreferrer">https://github.com/linlinjava/litemall</a> （又一个小商城，litemall = Spring Boot 后端 + Vue 管理员前端 + 微信小程序用户前端 + Vue 用户移动端）</li><li>xmall： <a href="https://github.com/Exrick/xmall" target="_blank" rel="noreferrer">https://github.com/Exrick/xmall</a> （基于SOA架构的分布式电商购物商城 前后端分离 前台商城:Vue全家桶 后台管理系统）</li><li>miaosha： <a href="https://github.com/qiurunze123/miaosha" target="_blank" rel="noreferrer">https://github.com/qiurunze123/miaosha</a> （秒杀系统设计和实现）</li><li>SecKill： <a href="https://github.com/hfbin/Seckill" target="_blank" rel="noreferrer">https://github.com/hfbin/Seckill</a> （基于 SpringBoot+Mybatis+Redis+RabbitMQ 秒杀系统）</li></ul><h4 id="博客论坛" tabindex="-1">博客论坛 <a class="header-anchor" href="#博客论坛" aria-label="Permalink to &quot;博客论坛&quot;">​</a></h4><ul><li><a href="https://github.com/langhsu/mblog" target="_blank" rel="noreferrer">Mblog</a> ：开源 Java 博客系统</li><li><a href="https://github.com/halo-dev/halo" target="_blank" rel="noreferrer">halo</a> ：一个优秀的开源博客发布应用</li><li><a href="https://github.com/Qbian61/forum-java" target="_blank" rel="noreferrer">forum-java</a> ：一款用 Java（spring boot） 实现的现代化社区（论坛/问答/BBS/社交网络/博客）系统平台</li><li><a href="https://github.com/lenve/vhr" target="_blank" rel="noreferrer">vhr</a> ：微人事是一个前后端分离的人力资源管理系统，项目采用 SpringBoot+Vue 开发。</li><li><a href="https://github.com/cloudfavorites/favorites-web" target="_blank" rel="noreferrer">favorites-web</a>:云收藏 Spring Boot 2.X 开源项目。云收藏是一个使用 Spring Boot 构建的开源网站，可以让用户在线随时随地收藏的一个网站，在网站上分类整理收藏的网站或者文章。</li><li><a href="https://github.com/codedrinker/community" target="_blank" rel="noreferrer">community</a> ：码问，开源论坛、问答系统，现有功能提问、回复、通知、最新、最热、消除零回复功能。技术栈 Spring、Spring Boot、MyBatis、MySQL/H2、Bootstrap</li><li><a href="https://github.com/yourkevin/NiterForum" target="_blank" rel="noreferrer">NiterForum</a> ：尼特社区-NiterForum-一个论坛/社区程序。后端Springboot/MyBatis/Maven/MySQL，前端Thymeleaf/Layui。可供初学者，学习、交流使用。</li><li><a href="https://github.com/lenve/VBlog" target="_blank" rel="noreferrer">VBlog</a> ：V部落，Vue+SpringBoot实现的多用户博客管理平台!</li><li><a href="https://github.com/damoqiongqiu/NiceFish" target="_blank" rel="noreferrer">NiceFish</a> ：SpringBoot/SpringCloud 前后端分离项目</li><li><a href="https://github.com/ZHENFENG13/My-Blog" target="_blank" rel="noreferrer">My-Blog</a> ： My Blog 是由 SpringBoot + Mybatis + Thymeleaf 等技术实现的 Java 博客系统，页面美观、功能齐全、部署简单及完善的代码。</li><li><a href="https://github.com/ZHENFENG13/My-Blog-layui" target="_blank" rel="noreferrer">My-Blog-layui</a> ：layui 版本的 My-Blog，由 SpringBoot + Layui + Mybatis + Thymeleaf 等技术实现的 Java 博客系统。</li><li><a href="https://github.com/88250/symphony" target="_blank" rel="noreferrer">symphony</a> ：Java 实现的现代化社区</li></ul><h4 id="管理系统" tabindex="-1">管理系统 <a class="header-anchor" href="#管理系统" aria-label="Permalink to &quot;管理系统&quot;">​</a></h4><ul><li><a href="https://github.com/wxiaoqi/Spring-Cloud-Admin" target="_blank" rel="noreferrer">Spring-Cloud-Admin</a> ：Cloud-Admin 是国内首个基于 Spring Cloud 微服务化开发平台，具有统一授权、认证后台管理系统，其中包含具备用户管理、资源权限管理、网关 API 管理等多个模块，支持多业务系统并行开发，可以作为后端服务的开发脚手架。代码简洁，架构清晰，适合学习和直接项目中使用。核心技术采用 Spring Boot2 以及 Spring Cloud Gateway 相关核心组件，前端采用 vue-element-admin 组件。</li><li><a href="https://github.com/tomsun28/bootshiro" target="_blank" rel="noreferrer">bootshiro</a> ：基于 springboot+shiro+jwt 的资源无状态认证权限管理系统后端</li><li><a href="https://github.com/72crm/72crm-java" target="_blank" rel="noreferrer">悟空CRM</a> ：基于jfinal+vue+ElementUI的前后端分离CRM系统</li><li><a href="https://github.com/elunez/eladmin" target="_blank" rel="noreferrer">EL-ADMIN</a> ：基于 SpringBoot 的后台管理系统</li><li><a href="https://gitee.com/log4j/pig" target="_blank" rel="noreferrer">pig</a> ：基于 Spring Boot 2.2、 Spring Cloud Hoxton &amp; Alibaba、 OAuth2 的 RBAC 权限管理系统。</li><li><a href="https://github.com/Heeexy/SpringBoot-Shiro-Vue" target="_blank" rel="noreferrer">Spring Boot-Shiro-Vue</a> ：基于Spring Boot-Shiro-Vue 的权限管理</li><li><a href="https://github.com/ZeroWdd/studentmanager" target="_blank" rel="noreferrer">studentmanager</a> ：基于springboot+mybatis学生管理系统</li><li><a href="https://github.com/jishenghua/jshERP" target="_blank" rel="noreferrer">jshERP</a> ：华夏ERP基于SpringBoot框架和SaaS模式，立志为中小企业提供开源好用的ERP软件，目前专注进销存+财务功能。主要模块有零售管理、采购管理、销售管理、仓库管理、财务管理、报表查询、系统管理等。支持预付款、收入支出、仓库调拨、组装拆卸、订单等特色功能。拥有库存状况、出入库统计等报表。同时对角色和权限进行了细致全面控制，精确到每个按钮和菜单。</li><li><a href="https://github.com/misterchaos/HotelSystem" target="_blank" rel="noreferrer">HotelSystem</a> ：酒店管理系统 Java,tomcat,mysql,servlet,jsp实现，没有使用任何框架</li></ul><h4 id="开发平台" tabindex="-1">开发平台 <a class="header-anchor" href="#开发平台" aria-label="Permalink to &quot;开发平台&quot;">​</a></h4><ul><li><a href="https://github.com/2014shijina2014/open-capacity-platform" target="_blank" rel="noreferrer">open-capacity-platform</a> ：微服务能力开发平台</li><li><a href="https://github.com/zhangdaiscott/jeecg-boot" target="_blank" rel="noreferrer">jeecg-boot</a> ：JeecgBoot是一款基于BPM的低代码平台！前后端分离架构 SpringBoot 2.x，SpringCloud，Ant Design&amp;Vue，Mybatis-plus，Shiro，JWT，支持微服务。强大的代码生成器让前后端代码一键生成，实现低代码开发！</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li><a href="https://github.com/mindskip/xzs" target="_blank" rel="noreferrer">学之思在线考试系统</a> ：一款 java + vue 的前后端分离的考试系统</li><li><a href="https://github.com/Jackson0714/PassJava-Platform" target="_blank" rel="noreferrer">PassJava-Platform</a> ：一款面试刷题的 Spring Cloud 开源系统</li><li><a href="https://github.com/kekingcn/kkFileView" target="_blank" rel="noreferrer">kkFileView</a> ：使用spring boot打造文件文档在线预览项目</li><li><a href="https://github.com/baomidou/dynamic-datasource-spring-boot-starter" target="_blank" rel="noreferrer">dynamic-datasource</a> ：一个基于springboot的快速集成多数据源的启动器</li><li><a href="https://github.com/373675032/moti-cloud" target="_blank" rel="noreferrer">moti-cloud</a> ：莫提网盘，基于 SpringBoot+MyBatis+ThymeLeaf+BootStrap，适合初学者</li><li><a href="https://github.com/qiurunze123/threadandjuc" target="_blank" rel="noreferrer">threadandjuc</a> ：three-high-import 高可用\\高可靠\\高性能，三高多线程导入系统（该项目意义为理论贯通)</li><li><a href="https://github.com/proxyee-down-org/proxyee-down" target="_blank" rel="noreferrer">proxyee-down</a> ：http下载工具，基于http代理，支持多连接分块下载</li><li><a href="https://github.com/sfturing/hosp_order" target="_blank" rel="noreferrer">hosp_order</a> ：医院预约挂号系统，基于 SSM 框架</li><li><a href="https://how2j.cn/module/170.html" target="_blank" rel="noreferrer">趋势投资 SpringCloud</a></li><li><a href="https://how2j.cn/module/176.html" target="_blank" rel="noreferrer">DiyTomcat</a></li></ul><h2 id="阶段-6-java-高级" tabindex="-1">阶段 6：Java 高级 <a class="header-anchor" href="#阶段-6-java-高级" aria-label="Permalink to &quot;阶段 6：Java 高级&quot;">​</a></h2><h3 id="目标-5" tabindex="-1">目标 <a class="header-anchor" href="#目标-5" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>不满足于能做，而是通过更 <strong>深入</strong> 和 <strong>广泛</strong> 的学习，实现高质量的代码和更优秀的架构，培养解决问题的能力。</p><p>到了这个阶段，‌‌‌‌你已经不是 Java 新手⁢⁢⁢⁢了，而是一个能独立做项目的开⁡⁡⁡⁡发者。但是如果想进大厂、拿高薪，或者想在技术上有更⁠⁠⁠⁠深的造诣，就需要继续深入学习。</p><p>这个阶段的学习，不能只‌‌‌‌是被动地看教程了。建议除了看完整的教程外，平⁢⁢⁢⁢时多自主搜索信息去学习，积少成多。比如遇到了⁡⁡⁡⁡一个不了解的名词（比如虚拟线程、ZGC），可以去网上搜一下，感兴趣的话再进行下一步的学习⁠⁠⁠⁠。慢慢地，你的知识面就会越来越广。</p><h3 id="🌖-并发编程-21-天" tabindex="-1">🌖 并发编程（21 天） <a class="header-anchor" href="#🌖-并发编程-21-天" aria-label="Permalink to &quot;🌖 并发编程（21 天）&quot;">​</a></h3><p>对 Java 后‌‌‌‌端开发程序员来说，懂得如何利用有⁢⁢⁢⁢限的系统资源来提高系统的性能是很⁡⁡⁡⁡重要的，也是大厂面试考察的重点，因此并发编程（尤其是 Java ⁠⁠⁠⁠并发包的使用）这块的知识很重要。</p><p>把它放到高‌‌‌‌级，是因为在学⁢⁢并⁢发⁢编程前，需⁡⁡要有⁡一定⁡的编程经验、了解一定⁠⁠的操作⁠系统知识。</p><h4 id="知识-20" tabindex="-1">知识 <a class="header-anchor" href="#知识-20" aria-label="Permalink to &quot;知识&quot;">​</a></h4><p><strong>传统并发编程【必学】：</strong></p><ul><li>线程和进程</li><li>线程状态</li><li>并行和并发</li><li>同步和异步</li><li>Synchronized</li><li>Volatile 关键字</li><li>Lock 锁</li><li>死锁</li><li>可重入锁</li><li>线程安全</li><li>线程池</li><li>JUC 的使用</li><li>AQS</li><li>Fork Join</li><li>CAS</li></ul><p><strong>新特性【了解】：</strong></p><ul><li><strong>虚拟线程（Virtual Threads）</strong> ：Java 21 引入的重要特性，是轻量级的线程，可以极大提升并发性能。虚拟线程让我们能够以更低的资源开销创建数百万个线程，特别适合 I/O 密集型应用。感兴趣的同学可以查看 <a href="https://www.codefather.cn/course/java/section/1962801453192523778" target="_blank" rel="noreferrer">Java 21 新特性</a> 。</li><li>结构化并发（Structured Concurrency）：让并发代码更易于理解和维护</li></ul><h4 id="学习建议-22" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-22" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>并发编程入门不难，依然是 <strong>先学会使用</strong> 基础的 Java 并发包， 再通过大量地实践和测试，了解一些原理，才能真正掌握何时使用、如何更合理地使用并发编程。而不是张口闭口多线程，上天入地高并发。</p><p>对于虚拟线程这类新特‌‌‌‌性，初学者先不用着急学，等你掌握了传统⁢⁢⁢⁢的并发编程知识后，再去了解会更有收获。⁡⁡⁡⁡但如果你的项目中有大量的 I/O 操作（比如网络请求、数据库查询），了解虚拟⁠⁠⁠⁠线程能帮你写出性能更好的代码。</p><h4 id="经典面试题-15" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-15" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>volatile 关键字的作用</li><li>使用线程池有哪些好处？</li><li>线程池参数如何设置？</li><li>什么是线程安全问题，如何解决？</li><li>介绍 synchronized 的锁升级机制</li><li>CopyOnWriteArrayList 适用于哪种场景？</li></ol><h4 id="资源-20" tabindex="-1">资源 <a class="header-anchor" href="#资源-20" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.codefather.cn/course/1790950013153095682" target="_blank" rel="noreferrer">伙伴匹配系统 - 鱼皮原创</a> ：项目中运用并发编程解决实际问题</li><li>⭐ <a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">智能 BI 项目 - 鱼皮原创</a> ：运用线程池、并发编程</li><li>⭐ <a href="https://yuyuanweb.feishu.cn/wiki/SePYwTc9tipQiCktw7Uc7kujnCd" target="_blank" rel="noreferrer">OJ 判题系统 - 鱼皮原创</a> ：运用并发编程</li><li>⭐ <a href="https://www.bilibili.com/video/BV1Kw411Z7dF" target="_blank" rel="noreferrer">尚硅谷 - 大厂必备技术之 JUC 并发编程 2021 最新版</a> ：短、精、新</li><li><a href="https://www.bilibili.com/video/BV16J411h7Rd" target="_blank" rel="noreferrer">黑马程序员 - 全面深入学习 Java 并发编程</a> ：讲得很细、全面深入</li><li>《Java 并发编程实战》：国外经典书籍</li><li>《Java 并发编程艺术》：国人写的，理论思想内容较多，有时间建议反复看</li><li><a href="https://www.aliyundrive.com/s/MBKzUxWWBbe" target="_blank" rel="noreferrer">《图解 Java 多线程设计模式》</a> ：提取码: 9gc7，可以额外学习多线程设计模式</li><li><a href="https://github.com/CL0610/Java-concurrency" target="_blank" rel="noreferrer">Java 并发知识点总结</a></li></ul><h3 id="🌖-jvm-30-天" tabindex="-1">🌖 JVM（30 天） <a class="header-anchor" href="#🌖-jvm-30-天" aria-label="Permalink to &quot;🌖 JVM（30 天）&quot;">​</a></h3><p>想要深入理‌‌解‌‌ Java，探⁢秘⁢ Java ⁢⁢跨⁡平台⁡的奥秘，一定要了解⁡⁡ Java⁠ 底层的虚⁠拟机技术。               ⁠⁠</p><p>了解虚拟机‌‌‌‌、掌握虚拟机性⁢⁢能⁢调⁢优方法，有⁡⁡助于⁡你写⁡出更高性能、资源占用⁠⁠更小的⁠优质程序。</p><p>在学习 J‌‌‌‌VM 的过程⁢中⁢，⁢也⁢能学到⁡很多⁡精妙⁡的设⁡计，开拓思路。</p><h4 id="知识-21" tabindex="-1">知识 <a class="header-anchor" href="#知识-21" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>JVM 内存结构</li><li>JVM 生命周期</li><li>主流虚拟机</li><li>Java 代码执行流程</li><li>类加载 <ul><li>类加载器 <ul><li>类加载过程</li><li>双亲委派机制</li></ul></li></ul></li><li>垃圾回收 <ul><li>垃圾回收器 <ul><li>垃圾回收策略</li><li>垃圾回收算法</li><li>StopTheWorld</li></ul></li></ul></li><li>字节码</li><li>内存分配和回收</li><li>JVM 性能调优 <ul><li>性能分析方法 <ul><li>常用工具</li><li>参数设置</li></ul></li></ul></li><li>Java 探针</li><li>线上故障分析</li></ul><h4 id="学习建议-23" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-23" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>JVM 是 J‌‌‌‌ava 的灵魂，想要深入理解⁢⁢⁢⁢ Java、写出高性能的代码⁡⁡⁡⁡，JVM 是必学的。但是 JVM 的知识确实有点枯燥，不⁠⁠⁠⁠像框架那样能立刻做出东西来。</p><p>建议先看视频入门，有实操‌‌‌‌的地方一定要实操！比如分析 GC 日志、使用 ⁢⁢⁢⁢JVisualVM 查看内存使用情况、通过参数调⁡⁡⁡⁡优等。光看理论很难理解，自己动手分析过一次，印象会深刻很多                ⁠⁠⁠⁠</p><p>第一遍看不懂很正常，‌‌‌‌JVM 涉及很多底层知识。可以先快速过一⁢⁢⁢⁢遍视频，有个大致印象，再去看书（比如《深⁡⁡⁡⁡入理解 Java 虚拟机（第三版）》）巩固，最后面试前再刷一遍，这样效果会好很多⁠⁠⁠⁠。我当时就是看了三遍才真正理解的。</p><p>注意，不同目标有不同的学法：</p><ul><li>如果只是为了通过面试，可以直接看更精简的视频（比如狂神的 JVM 快速入门），重点背一下常见面试题就行。</li><li>如果想真正学好 JVM、做性能调优，那《深入理解 Java 虚拟机（第三版）》一定要读，而且要边读边实践。</li></ul><h4 id="经典面试题-16" tabindex="-1">经典面试题 <a class="header-anchor" href="#经典面试题-16" aria-label="Permalink to &quot;经典面试题&quot;">​</a></h4><ol><li>介绍 JVM 的内存模型？</li><li>JVM 内存为什么要分代？</li><li>介绍一次完整的 GC 流程</li><li>介绍双亲委派模型，为什么需要它？</li></ol><h4 id="资源-21" tabindex="-1">资源 <a class="header-anchor" href="#资源-21" aria-label="Permalink to &quot;资源&quot;">​</a></h4><ul><li>⭐ <a href="https://www.bilibili.com/video/BV1PJ411n7xZ" target="_blank" rel="noreferrer">尚硅谷宋红康 - JVM 全套教程详解</a> ：讲得相当全面！附有实操</li><li><a href="https://www.bilibili.com/video/BV1iJ411d7jS" target="_blank" rel="noreferrer">狂神说 Java - JVM 快速入门篇</a> ：讲得有点浅，但都是面试重点，时间紧可以直接看这个</li><li>《深入理解 Java 虚拟机（第三版）》：有理论有实践，内容丰富，JVM 学习神书</li><li><a href="https://github.com/doocs/jvm" target="_blank" rel="noreferrer">Java 虚拟机底层原理知识总结</a></li><li><a href="https://developer.aliyun.com/graph/java/point/64" target="_blank" rel="noreferrer">阿里云 JVM 实战</a></li><li><a href="https://github.com/alibaba/arthas" target="_blank" rel="noreferrer">Arthas 开源 Java 诊断工具</a></li></ul><h3 id="🌖-java-高级知识" tabindex="-1">🌖 Java 高级知识 <a class="header-anchor" href="#🌖-java-高级知识" aria-label="Permalink to &quot;🌖 Java 高级知识&quot;">​</a></h3><blockquote><p>通过阅读文章了解即可</p></blockquote><h4 id="知识-22" tabindex="-1">知识 <a class="header-anchor" href="#知识-22" aria-label="Permalink to &quot;知识&quot;">​</a></h4><ul><li>动态代理</li><li>Java 探针</li><li>字节码</li><li>UnSafe 类</li><li>协程 / 纤程</li></ul><h3 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h3><h4 id="🌖-分布式" tabindex="-1">🌖 分布式 <a class="header-anchor" href="#🌖-分布式" aria-label="Permalink to &quot;🌖 分布式&quot;">​</a></h4><ul><li>分布式理论 <ul><li>CAP <ul><li>BASE</li></ul></li></ul></li><li>分布式缓存 <ul><li>Redis <ul><li>Memcached</li><li>Etcd</li></ul></li></ul></li><li>一致性算法 <ul><li>Raft <ul><li>Paxos</li><li>一致性哈希</li></ul></li></ul></li><li>分布式事务 <ul><li>解决方案 <ul><li>2PC - 3PC - TCC - 本地消息表 - MQ 事务消息 - 最大努力通知</li><li><a href="https://github.com/codingapi/tx-lcn" target="_blank" rel="noreferrer">LCN 分布式事务框架</a></li></ul></li></ul></li><li>分布式 id 生成 <ul><li><a href="https://github.com/Meituan-Dianping/Leaf" target="_blank" rel="noreferrer">Leaf 分布式 id 生成服务</a></li></ul></li><li>分布式任务调度 <ul><li><a href="https://www.xuxueli.com/xxl-job/" target="_blank" rel="noreferrer">XXL-JOB 调度平台</a><ul><li><a href="https://gitee.com/elasticjob/elastic-job" target="_blank" rel="noreferrer">elastic-job</a></li></ul></li></ul></li><li>分布式服务调用 <ul><li>trpc</li></ul></li><li>分布式存储 <ul><li>HDFS <ul><li>Ceph</li></ul></li></ul></li><li>分布式数据库 <ul><li>TiDB <ul><li>OceanBase</li></ul></li></ul></li><li>分布式文件系统 <ul><li>HDFS</li></ul></li><li>分布式协调 <ul><li>Zookeeper</li></ul></li><li>分布式监控 <ul><li>Prometheus <ul><li>Zabbix</li></ul></li></ul></li><li>分布式消息队列 <ul><li>RabbitMQ <ul><li>Kafka</li><li>Apache Pulsar</li></ul></li></ul></li><li>分布式日志收集 <ul><li>Elastic Stack <ul><li>Loki</li></ul></li></ul></li><li>分布式搜索引擎 <ul><li>Elasticsearch</li></ul></li><li>分布式链路追踪 <ul><li>Apache SkyWalking</li></ul></li><li>分布式配置中心 <ul><li>Apollo <ul><li>Nacos</li></ul></li></ul></li></ul><h4 id="🌗-高可用" tabindex="-1">🌗 高可用 <a class="header-anchor" href="#🌗-高可用" aria-label="Permalink to &quot;🌗 高可用&quot;">​</a></h4><ul><li>限流</li><li>降级熔断</li><li>冷备</li><li>双机热备</li><li>同城双活</li><li>异地双活</li><li>异地多活</li><li>容灾备份</li></ul><h4 id="🌗-高并发" tabindex="-1">🌗 高并发 <a class="header-anchor" href="#🌗-高并发" aria-label="Permalink to &quot;🌗 高并发&quot;">​</a></h4><ul><li>数据库 <ul><li>分库分表 <ul><li>MyCat 中间件 - Apache ShardingSphere 中间件</li><li>读写分离</li></ul></li></ul></li><li>缓存 <ul><li>缓存雪崩 <ul><li>缓存击穿</li><li>缓存穿透</li></ul></li></ul></li><li>负载均衡 <ul><li>负载均衡算法 <ul><li>软硬件负载均衡（2、3、4、7 层）</li></ul></li></ul></li></ul><h4 id="🌘-服务网格" tabindex="-1">🌘 服务网格 <a class="header-anchor" href="#🌘-服务网格" aria-label="Permalink to &quot;🌘 服务网格&quot;">​</a></h4><p>服务网格用来描述组‌‌‌‌成应用程序的微服务网络以及它们之间⁢⁢⁢的交⁢互。服务网格的规模和复杂性不断⁡⁡⁡⁡的增长，它将会变得越来越难以理解和管理，常见的需求包括服务发现、负载⁠⁠⁠⁠均衡、故障恢复、度量和监控等。</p><h5 id="知识-23" tabindex="-1">知识 <a class="header-anchor" href="#知识-23" aria-label="Permalink to &quot;知识&quot;">​</a></h5><ul><li>Istio <ul><li>流量管理 <ul><li>安全性</li><li>可观测性</li></ul></li></ul></li><li>Envoy（开源的边缘和服务代理）</li></ul><h5 id="资源-22" tabindex="-1">资源 <a class="header-anchor" href="#资源-22" aria-label="Permalink to &quot;资源&quot;">​</a></h5><ul><li>istio 官方文档： <a href="https://preliminary.istio.io/latest/zh" target="_blank" rel="noreferrer">https://preliminary.istio.io/latest/zh</a></li><li>istio 视频教程： <a href="https://www.bilibili.com/video/BV1Lf4y1x7j8" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Lf4y1x7j8</a></li></ul><h4 id="🌘-ddd-领域驱动设计" tabindex="-1">🌘 DDD 领域驱动设计 <a class="header-anchor" href="#🌘-ddd-领域驱动设计" aria-label="Permalink to &quot;🌘 DDD 领域驱动设计&quot;">​</a></h4><p>将数据、业‌‌‌‌务流程抽象成容⁢⁢易⁢理⁢解的领域模⁡⁡型，⁡通过⁡用代码实现领域模型，⁠⁠来组成完⁠整的⁠业务系统。</p><h5 id="知识-24" tabindex="-1">知识 <a class="header-anchor" href="#知识-24" aria-label="Permalink to &quot;知识&quot;">​</a></h5><ul><li>DDD 的优势</li><li>DDD 的适用场景</li><li>DDD 核心概念 <ul><li>领域模型分类：失血、贫血、充血、涨血 <ul><li>子域划分：核心域、通用域、支撑域</li><li>限界上下文</li><li>实体和值对象</li><li>聚合设计</li><li>领域事件</li></ul></li></ul></li><li>DDD 实践</li></ul><h5 id="资源-23" tabindex="-1">资源 <a class="header-anchor" href="#资源-23" aria-label="Permalink to &quot;资源&quot;">​</a></h5><ul><li>⭐ <a href="https://www.codefather.cn/course/1864210260732116994" target="_blank" rel="noreferrer">智能协同云图库项目 - 鱼皮原创</a> ：实战 DDD 领域驱动设计开发企业级项目</li><li><a href="https://github.com/heynickc/awesome-ddd" target="_blank" rel="noreferrer">DDD 资源大全</a></li></ul><h4 id="🌘-其他" tabindex="-1">🌘 其他 <a class="header-anchor" href="#🌘-其他" aria-label="Permalink to &quot;🌘 其他&quot;">​</a></h4><ul><li>Sidecar</li><li>Serverless</li><li>云原生</li></ul><h4 id="学习建议-24" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-24" aria-label="Permalink to &quot;学习建议&quot;">​</a></h4><p>架构设计的‌‌‌‌学习没有顶点，多⁢⁢⁢看⁢文章，思考每种⁡⁡⁡设计⁡的优缺点和适用场景，有机会的⁠⁠⁠话在企业中⁠实践即可。</p><p>还在学校、或者初入这行的同‌‌‌‌学切记，千万不要一味地去背诵架构设计的八股文。你可以⁢⁢⁢⁢背，但是这一块的知识只有结合具体的项目才有意义，所以⁡⁡⁡⁡要多做项目去实践设计的合理性，而不是什么设计都咔咔往系统里去怼。比如面试问到分布式事务，能结合自己项目中⁠⁠⁠⁠用分布式事务解决问题的经验去回答最好。</p><h3 id="🌘-其他技术" tabindex="-1">🌘 其他技术 <a class="header-anchor" href="#🌘-其他技术" aria-label="Permalink to &quot;🌘 其他技术&quot;">​</a></h3><ul><li>热数据探测技术：京东 HotKey</li><li>数据库流水订阅：阿里 Canal</li><li>监控告警</li><li>应用安全</li><li>故障演练</li><li>流量回放</li></ul><h2 id="阶段-7-java-求职" tabindex="-1">阶段 7：Java 求职 <a class="header-anchor" href="#阶段-7-java-求职" aria-label="Permalink to &quot;阶段 7：Java 求职&quot;">​</a></h2><h3 id="目标-6" tabindex="-1">目标 <a class="header-anchor" href="#目标-6" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>一句话：找到好工作</p><h3 id="学习建议-25" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-25" aria-label="Permalink to &quot;学习建议&quot;">​</a></h3><p>找工作是一‌‌‌‌个系统工程，⁢不⁢是⁢简⁢单地投⁡简历⁡、面⁡试就⁡行了。下面分享⁠一些我⁠的经验和⁠建议：</p><p>1）尽早做规划，可以通过大厂招聘官网的岗位描述来了解岗位的要求，看看自己还欠缺哪些技能。 <strong>建议至少提前 3 个月开始准备</strong> ，不要等到要找工作了才开始慌。</p><p>推荐阅读鱼皮的 <a href="https://www.codefather.cn/course/job" target="_blank" rel="noreferrer">保姆级求职指南</a> ，从求职规划到拿 Offer 全流程讲解。</p><p>2）打磨简历：简历是你的第一张名片，一份好的简历能让你获得更多面试机会。建议使用 <a href="https://www.laoyujianli.com/" target="_blank" rel="noreferrer">老鱼简历</a> 制作简历，有大量专业简历模板。</p><p><img src="https://pic.code-nav.cn/migrate_image/462551fa59eb8310352c773534e7fd6d.webp" alt=""></p><p>关于如何写好简历，推荐学习鱼皮的 <a href="https://www.codefather.cn/course/1802644557818343425" target="_blank" rel="noreferrer">保姆级写简历指南</a> 。还可以查看 <a href="https://www.codefather.cn/job/resume" target="_blank" rel="noreferrer">真实简历案例</a> ，看看别人的简历是怎么写的。</p><p>3）多刷面试题：建议使用 <a href="https://www.mianshiya.com/" target="_blank" rel="noreferrer">面试鸭</a> 刷题，支持按公司、题型、难度筛选。</p><p><img src="https://pic.code-nav.cn/migrate_image/8591f8bddc6d55a13b0e09063f821d7b.webp" alt=""></p><p>如果要进大‌‌‌‌厂的话，还需要⁢⁢坚⁢持⁢刷算法题（⁡⁡Le⁡et⁡Code），每天 1⁠⁠-2 道，保⁠持手⁠感。</p><p>4）多看面经和面试视频：</p><ul><li>编程导航整理了大量 <a href="https://www.codefather.cn/job/experience" target="_blank" rel="noreferrer">真实面经</a> ，看看别人都被问了什么</li><li>观看 <a href="https://www.codefather.cn/mockInterview" target="_blank" rel="noreferrer">几百场真实面试视频</a> ，学习面试技巧</li><li>关注 <a href="https://space.bilibili.com/3546383483144655" target="_blank" rel="noreferrer">面试鸭 B 站账号</a> ，看面试题讲解视频</li><li>查看 <a href="https://www.codefather.cn/learn?category=76&amp;type=2" target="_blank" rel="noreferrer">编程导航求职干货分享</a></li></ul><p>5）多参加面试：‌‌‌‌不要等准备得很充分了才去面试，⁢⁢⁢⁢可以先拿一些不太想去的公司练手⁡⁡⁡⁡，积累面试经验。每次面试后都要复盘总结，记录下被问到的问题和⁠⁠⁠⁠自己答得不好的地方，下次改进。</p><p>还可以利用 AI 进行 <a href="https://ai.mianshiya.com/" target="_blank" rel="noreferrer">1 对 1 模拟面试</a> ，消除真实面试时的紧张感。</p><h3 id="资源-24" tabindex="-1">资源 <a class="header-anchor" href="#资源-24" aria-label="Permalink to &quot;资源&quot;">​</a></h3><h4 id="校招岗位" tabindex="-1">校招岗位 <a class="header-anchor" href="#校招岗位" aria-label="Permalink to &quot;校招岗位&quot;">​</a></h4><ul><li>阿里 Java 开发： <a href="https://campus.alibaba.com/position.htm?refno=12699" target="_blank" rel="noreferrer">https://campus.alibaba.com/position.htm?refno=12699</a></li><li>腾讯后台开发： <a href="https://join.qq.com/post_detail.html?pid=1&amp;id=101&amp;tid=2" target="_blank" rel="noreferrer">https://join.qq.com/post_detail.html?pid=1&amp;id=101&amp;tid=2</a></li><li>腾讯全栈开发： <a href="https://join.qq.com/post_detail.html?pid=1&amp;id=137&amp;tid=2" target="_blank" rel="noreferrer">https://join.qq.com/post_detail.html?pid=1&amp;id=137&amp;tid=2</a></li><li>腾讯运营开发： <a href="https://join.qq.com/post_detail.html?pid=1&amp;id=105&amp;tid=2" target="_blank" rel="noreferrer">https://join.qq.com/post_detail.html?pid=1&amp;id=105&amp;tid=2</a></li><li>美团后端开发： <a href="https://campus.meituan.com/jobs?jobFamily=1&amp;jobId=4005&amp;jobType=1&amp;pageNo=2" target="_blank" rel="noreferrer">https://campus.meituan.com/jobs?jobFamily=1&amp;jobId=4005&amp;jobType=1&amp;pageNo=2</a></li></ul><h4 id="社招岗位" tabindex="-1">社招岗位 <a class="header-anchor" href="#社招岗位" aria-label="Permalink to &quot;社招岗位&quot;">​</a></h4><ul><li>阿里社招： <a href="https://job.alibaba.com/zhaopin/positionList.htm" target="_blank" rel="noreferrer">https://job.alibaba.com/zhaopin/positionList.htm</a></li><li>腾讯社招： <a href="https://careers.tencent.com/search.html" target="_blank" rel="noreferrer">https://careers.tencent.com/search.html</a></li></ul><h4 id="实习" tabindex="-1">实习 <a class="header-anchor" href="#实习" aria-label="Permalink to &quot;实习&quot;">​</a></h4><ul><li>实习僧： <a href="https://www.shixiseng.com/" target="_blank" rel="noreferrer">https://www.shixiseng.com/</a></li></ul><h4 id="鱼皮经历" tabindex="-1">鱼皮经历 <a class="header-anchor" href="#鱼皮经历" aria-label="Permalink to &quot;鱼皮经历&quot;">​</a></h4><ul><li>⭐ <a href="https://www.codefather.cn/post/1815179408534896642" target="_blank" rel="noreferrer">我学计算机的四年，共勉</a> （从 0 开始的编程学习进大厂经历）</li><li>⭐ <a href="https://www.codefather.cn/post/1815180733469392898" target="_blank" rel="noreferrer">我的第一份实习</a></li><li>⭐ <a href="https://www.codefather.cn/post/1815180628049756161" target="_blank" rel="noreferrer">我的第二份实习，字节跳动</a></li></ul><h4 id="知识总结" tabindex="-1">知识总结 <a class="header-anchor" href="#知识总结" aria-label="Permalink to &quot;知识总结&quot;">​</a></h4><ul><li><a href="https://developer.aliyun.com/graph/java" target="_blank" rel="noreferrer">阿里 Java 技术图谱</a></li></ul><h4 id="面试题刷题" tabindex="-1">面试题刷题 <a class="header-anchor" href="#面试题刷题" aria-label="Permalink to &quot;面试题刷题&quot;">​</a></h4><ul><li>⭐ <a href="https://www.mianshiya.com/" target="_blank" rel="noreferrer">面试鸭 - Java 面试题库</a> （支持按题目、题型、难度、公司搜索，还有 AI 模拟面试）</li><li>⭐ <a href="https://www.codefather.cn/job/experience" target="_blank" rel="noreferrer">编程导航真实面经大全</a></li><li><a href="https://www.codefather.cn/job/experience" target="_blank" rel="noreferrer">编程导航面经汇总</a></li></ul><h4 id="面试题视频" tabindex="-1">面试题视频 <a class="header-anchor" href="#面试题视频" aria-label="Permalink to &quot;面试题视频&quot;">​</a></h4><p>更多面试题讲解视频，请关注 <a href="https://space.bilibili.com/3546383483144655" target="_blank" rel="noreferrer">面试鸭 B 站账号</a> 。</p><ul><li><a href="https://www.bilibili.com/video/BV1Hy4y1B78T" target="_blank" rel="noreferrer">尚硅谷 2021 逆袭版 Java 面试题第三季</a> （讲解面试高频题）</li><li><a href="https://www.bilibili.com/video/BV1yU4y1J7Bb" target="_blank" rel="noreferrer">阿里大佬透彻讲解 Java 面试 500 道必考题</a></li></ul><h2 id="阶段-8-持续学习" tabindex="-1">阶段 8：持续学习 <a class="header-anchor" href="#阶段-8-持续学习" aria-label="Permalink to &quot;阶段 8：持续学习&quot;">​</a></h2><h3 id="目标-7" tabindex="-1">目标 <a class="header-anchor" href="#目标-7" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>持续追求技术的深度和广度，培养自己的 <strong>核心竞争力</strong> 和 <strong>不可替代性</strong> ，学无止境！</p><h3 id="学习建议-26" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议-26" aria-label="Permalink to &quot;学习建议&quot;">​</a></h3><p>技术的学习‌‌‌‌永无止境，无论⁢⁢你⁢是⁢刚入行的新⁡⁡人，⁡还是⁡工作多年的老鸟，都要⁠⁠保持学⁠习的习惯。</p><p>1）自主学习‌‌‌‌能力：到了这个阶段，要培⁢⁢⁢⁢养自主学习的能力。遇到不⁡⁡⁡⁡懂的技术，要学会自己搜索资料、阅读官方文档、看⁠⁠源⁠⁠码。不要什么都等着别人来教你。</p><p>2）多看技术‌‌‌‌博客：关注一些优质的技⁢⁢⁢⁢术博客和技术团队（比如⁡⁡⁡⁡美团技术团队、阿里技术团队），看看大厂是怎么⁠⁠⁠⁠解决技术问题的，能开拓思路。</p><p>3）深度和广度‌‌‌‌并重：既要在某个领域深耕（⁢⁢⁢⁢比如精通 JVM 调优、精⁡⁡⁡⁡通并发编程），也要拓展知识面（了解前端、大数据、云⁠⁠⁠⁠原生等）。T 型人才更受欢迎。</p><p>4）多实践，多造轮‌‌‌‌子：光看不练假把式，要多动手实⁢⁢⁢⁢践。可以尝试自己实现一些常用的框架或工⁡⁡⁡⁡具，比如实现一个简单的 ORM 框架、实现一个 RPC 框架，这个过⁠⁠⁠⁠程会让你对技术的理解更深刻。</p><p>5）多交流，多分享：加入一些技术社区（比如 <a href="https://codefather.cn/" target="_blank" rel="noreferrer">编程导航</a> ），和其他开发者交流学习经验、分享技术心得。教是最好的学，尝试写技术博客、做技术分享，能帮你把知识真正内化。</p><h3 id="学习方向" tabindex="-1">学习方向 <a class="header-anchor" href="#学习方向" aria-label="Permalink to &quot;学习方向&quot;">​</a></h3><h4 id="框架源码" tabindex="-1">框架源码 <a class="header-anchor" href="#框架源码" aria-label="Permalink to &quot;框架源码&quot;">​</a></h4><ul><li>Spring</li><li>SpringBoot</li><li>SpringMVC</li><li>MyBatis</li><li>Netty</li><li>Dubbo</li><li>SpringCloud</li></ul><h4 id="计算机原理" tabindex="-1">计算机原理 <a class="header-anchor" href="#计算机原理" aria-label="Permalink to &quot;计算机原理&quot;">​</a></h4><ul><li>《算法导论》： <a href="https://www.bilibili.com/video/av48922404" target="_blank" rel="noreferrer">https://www.bilibili.com/video/av48922404</a></li><li>《现代操作系统》： <a href="https://www.bilibili.com/video/av9555596" target="_blank" rel="noreferrer">https://www.bilibili.com/video/av9555596</a></li><li>《深入理解计算机系统》： <a href="https://www.bilibili.com/video/av31289365" target="_blank" rel="noreferrer">https://www.bilibili.com/video/av31289365</a></li><li>《计算机网络：自顶向下方法》： <a href="https://www.bilibili.com/video/BV1JV411t7ow" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1JV411t7ow</a></li><li>《计算机程序的构造和解释》： <a href="https://www.bilibili.com/video/av8515129" target="_blank" rel="noreferrer">https://www.bilibili.com/video/av8515129</a></li><li>《数据库系统概论》： <a href="https://www.bilibili.com/video/BV1G54y1d7ZK" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1G54y1d7ZK</a></li></ul><h4 id="数据库-中间件-分布式" tabindex="-1">数据库 / 中间件 / 分布式 <a class="header-anchor" href="#数据库-中间件-分布式" aria-label="Permalink to &quot;数据库 / 中间件 / 分布式&quot;">​</a></h4><ul><li>数据库 <ul><li>MySQL <ul><li>PostgreSQL</li></ul></li></ul></li><li>缓存 <ul><li>Redis</li></ul></li><li>队列 <ul><li>Apache Kafka <ul><li>Apache Pulsar</li></ul></li></ul></li><li>搜索引擎 <ul><li>Elastic Stack <ul><li>Elasticsearch - logstash - kibana - beats</li></ul></li></ul></li><li>容器 <ul><li>Docker <ul><li>K8S</li></ul></li></ul></li></ul><h4 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h4><ul><li>广告系统</li><li>电商系统</li><li>搜索系统</li><li>支付转账</li><li>游戏后台</li><li>即时通讯</li><li>社交系统</li><li>CMS 系统</li><li>ERP 系统</li><li>OA 系统</li><li>代码生成</li><li>权限管理</li><li>秒杀活动</li></ul><h4 id="架构设计-1" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计-1" aria-label="Permalink to &quot;架构设计&quot;">​</a></h4><p>同阶段 6 的架构设计部分</p><h4 id="大数据" tabindex="-1">大数据 <a class="header-anchor" href="#大数据" aria-label="Permalink to &quot;大数据&quot;">​</a></h4><ul><li>5V 特点</li><li>Hadoop</li><li>HDFS</li><li>MapReduce</li><li>Spark</li><li>Flink</li><li>Storm</li><li>Hive</li><li>HBase</li><li>Druid</li><li>Kylin</li><li>Pig</li><li>Mahout</li></ul><h4 id="前沿技术" tabindex="-1">前沿技术 <a class="header-anchor" href="#前沿技术" aria-label="Permalink to &quot;前沿技术&quot;">​</a></h4><ul><li>云原生： <a href="https://www.jianshu.com/p/a37baa7c3eff" target="_blank" rel="noreferrer">https://www.jianshu.com/p/a37baa7c3eff</a><ul><li>Quasar Framework： <a href="http://www.quasarchs.com/" target="_blank" rel="noreferrer">http://www.quasarchs.com/</a></li></ul></li><li>服务网格： <a href="https://www.redhat.com/zh/topics/microservices/what-is-a-service-mesh" target="_blank" rel="noreferrer">https://www.redhat.com/zh/topics/microservices/what-is-a-service-mesh</a><ul><li>istio： <a href="https://github.com/istio/istio" target="_blank" rel="noreferrer">https://github.com/istio/istio</a><ul><li>官网： <a href="https://www.graalvm.org/" target="_blank" rel="noreferrer">https://www.graalvm.org/</a></li></ul></li></ul></li><li>ZGC： <a href="https://mp.weixin.qq.com/s/ag5u2EPObx7bZr7hkcrOTg" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/ag5u2EPObx7bZr7hkcrOTg</a> （新一代垃圾回收器） <ul><li>官网： <a href="http://openjdk.java.net/projects/zgc/" target="_blank" rel="noreferrer">http://openjdk.java.net/projects/zgc/</a></li></ul></li></ul><h3 id="自学-java-专题资源" tabindex="-1">自学 Java 专题资源 <a class="header-anchor" href="#自学-java-专题资源" aria-label="Permalink to &quot;自学 Java 专题资源&quot;">​</a></h3><ul><li>⭐ 编程导航： <a href="https://www.codefather.cn/" target="_blank" rel="noreferrer">https://www.codefather.cn/</a> （学习路线、项目教程、面试题、编程资源一站式平台）</li><li>⭐ GitHub Java 专区： <a href="https://github.com/topics/java" target="_blank" rel="noreferrer">https://github.com/topics/java</a></li><li>⭐ GitHub Java 合集： <a href="https://github.com/akullpp/awesome-java" target="_blank" rel="noreferrer">https://github.com/akullpp/awesome-java</a></li><li>StackOverflow： <a href="https://stackoverflow.com/questions/tagged/java" target="_blank" rel="noreferrer">https://stackoverflow.com/questions/tagged/java</a> （解决问题必备）</li><li>Netflix TechBlog： <a href="https://netflixtechblog.com/" target="_blank" rel="noreferrer">https://netflixtechblog.com/</a> （Netflix 微服务架构实践）</li><li>Uber Engineering Blog： <a href="https://www.uber.com/blog/engineering/" target="_blank" rel="noreferrer">https://www.uber.com/blog/engineering/</a> （Uber 大规模系统设计）</li><li>Airbnb Tech Blog： <a href="https://medium.com/airbnb-engineering" target="_blank" rel="noreferrer">https://medium.com/airbnb-engineering</a> （Airbnb 技术实践）</li><li>LinkedIn Engineering： <a href="https://www.linkedin.com/blog/engineering" target="_blank" rel="noreferrer">https://www.linkedin.com/blog/engineering</a> （LinkedIn 后端技术）</li><li>美团技术团队： <a href="https://tech.meituan.com/" target="_blank" rel="noreferrer">https://tech.meituan.com/</a></li><li>有赞技术团队： <a href="https://tech.youzan.com/tag/back-end/" target="_blank" rel="noreferrer">https://tech.youzan.com/tag/back-end/</a></li></ul><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>看完这份学‌‌‌‌习路线，你可能⁢⁢会⁢觉⁢得：天呐，⁡⁡Ja⁡va⁡ 要学的东西太多了，⁠⁠什么时候⁠才能学完⁠啊！</p><p>不要被吓到，‌‌‌‌这份路线涵盖了从零基础⁢⁢⁢⁢到高级的所有内容，不是⁡⁡⁡⁡所有的东西都要学完才能找工作的。根据你的目标⁠⁠⁠⁠和时间，可以有选择地学习：</p><ul><li><strong>如果你只有 6 个月</strong> ：学完阶段 1、3、5 就可以开始找工作了（语言基础 + 开发框架 + 项目实战）</li><li><strong>如果你有 1 年时间</strong> ：建议学完阶段 1 ~ 5，再选择性地学习阶段 4 和阶段 6 的部分内容</li><li><strong>如果你目标是大厂</strong> ：建议每个阶段都要学习，尤其是并发编程、JVM、微服务这些面试重点</li></ul><p>记住，学习路‌‌‌‌线只是一个参考，不是死板的⁢⁢教⁢⁢条。每个人的情况不同⁡⁡⁡⁡，要根据自己的实际情况灵活调整。重要的是保持学习⁠⁠⁠⁠的热情，不断实践，持续进步。</p><p>最后，祝大家学习顺利，早日找到心仪的工作！如果在学习过程中遇到问题，欢迎来 <a href="https://www.codefather.cn/" target="_blank" rel="noreferrer">编程导航</a> 和大家一起交流讨论～</p><p>加油小伙伴们 💪🏻！</p><p><img src="https://pic.code-nav.cn/migrate_image/66a502034e18abab9a459c9b237957f4.jpeg" alt=""></p><h2 id="程序员必备资源" tabindex="-1">程序员必备资源 <a class="header-anchor" href="#程序员必备资源" aria-label="Permalink to &quot;程序员必备资源&quot;">​</a></h2><p>1）程序员学习交流圈： <a href="https://www.codefather.cn/" target="_blank" rel="noreferrer">极客教程、实战项目、求职宝典</a></p><p>2）程序员面试八股文： <a href="https://www.mianshiya.com/" target="_blank" rel="noreferrer">实习/校招/社招高频考点、企业真题解析</a></p><p>3）程序员写简历神器： <a href="https://www.laoyujianli.com/" target="_blank" rel="noreferrer">专业模板、丰富例句、直通面试</a></p><p>4）AI 知识资源大全： <a href="https://ai.codefather.cn/" target="_blank" rel="noreferrer">前沿技术、最新 AI 资讯、提示词大全</a></p><p>5）1 对 1 模拟面试： <a href="https://ai.mianshiya.com/" target="_blank" rel="noreferrer">实习/校招/社招面试拿 Offer 必备</a></p>',609)])])}const f=e(t,[["render",o]]);export{p as __pageData,f as default};
